        const strict =
          input.collection === "docs" ||
          !this.getDefaultCollectionCandidates(input.collection).includes(explicitDir);
        const exists = await this.ensureDirectoryExists(
          absolutePath,
          `${input.collection}Dir`,
          explicitDir,
          strict
        );
        if (exists) {
          resolutions.push({ collection: input.collection, absolutePath });
        }
      }
      return resolutions;
    }

    const candidates = this.getDefaultCollectionCandidates(input.collection);
    for (const candidate of candidates) {
      const absolutePath = resolve(input.root, candidate);
      if (await this.directoryExists(absolutePath)) {
        return [{ collection: input.collection, absolutePath }];
      }
    }

    if (input.required) {
      const missing =
        input.collection === "docs" ? "content/docs or docs" : input.collection;
      throw this.createEntryInvalidError(
        `configured ${input.collection}Dir ${missing} does not exist`,
        input.root
      );
    }

    return [];
  }
  }

  private getExplicitCollectionDirectories(
    collection: DocsCollection,
    config: DocsConfig
  ): string[] {
    if (collection === "docs") {
      return this.normalizeConfiguredDirectories(
        config.content.docsDir ?? this.options.docsDir
      );
    }
    if (collection === "pages") {
      return this.normalizeConfiguredDirectories(
        config.content.pagesDir ?? this.options.pagesDir
      );
    }
    if (collection === "blog") {
      return this.normalizeConfiguredDirectories(
        config.content.blogDir ?? this.options.blogDir
      );
    }
    if (isNamedCollection(collection)) {
      const collectionId = getNamedCollectionId(collection);
      if (!collectionId) {
        return [];
      }
      return this.normalizeConfiguredDirectories(
        Object.entries(config.collections ?? {}).find(
          ([key]) => normalizeDatedCollectionId(key) === collectionId
        )?.[1].dir
      );
    }
    if (collection === "api") {
      return this.normalizeConfiguredDirectories(
        config.content.apiDir ?? this.options.apiDir
      );
    }
    return this.normalizeConfiguredDirectories(
      config.content.assetsDir ?? this.options.assetsDir
    );
  }

  private normalizeConfiguredDirectories(
    value: DocsContentDirectory | undefined
  ): string[] {
    if (!value) {
      return [];
    }
    return Array.isArray(value) ? value : [value];
  }

  private getDefaultCollectionCandidates(collection: DocsCollection): string[] {
    if (collection === "docs") {
      return ["content/docs", "docs"];
    }
    if (collection === "pages") {
      return ["pages"];
    }
    if (collection === "blog") {
      return ["blog"];
    }
    if (isNamedCollection(collection)) {
      return [];
    }
    if (collection === "api") {
      return ["api"];
    }
    return ["public", "assets"];
  }

  private async ensureDirectoryExists(
    absolutePath: string,
    key: string,
    configuredValue: string,
    strict: boolean
  ): Promise<boolean> {
    const stats = await this.tryStat(absolutePath);
    if (stats?.isDirectory()) {
      return true;
    }

    if (!strict) {
      return false;
    }

    throw this.createEntryInvalidError(
      `configured ${key} ${configuredValue} does not exist`,
      absolutePath
    );
  }

  private async directoryExists(absolutePath: string): Promise<boolean> {
    const stats = await this.tryStat(absolutePath);
    return Boolean(stats?.isDirectory());
  }

  private async tryStat(absolutePath: string) {
    try {
      return await stat(absolutePath);
    } catch {
      return null;
    }
  }

  private async collectCollectionEntries(
    collection: DocsCollection,
    absoluteDirectory: string
  ): Promise<DocsSourceEntry[]> {
    const filePaths = await fg("**/*", {
      cwd: absoluteDirectory,
      absolute: true,
      onlyFiles: true,
      dot: false,
      followSymbolicLinks: false,
      unique: true,
      suppressErrors: false,
    });

    const normalizedSortedPaths = filePaths.sort((left, right) =>
      normalizeProviderPath(left).localeCompare(normalizeProviderPath(right), "en", {
        sensitivity: "variant",
        numeric: true,
      })
    );

    const entries: DocsSourceEntry[] = [];
    for (const absolutePath of normalizedSortedPaths) {
      const relativePath = normalizeProviderPath(
        absolutePath.slice(absoluteDirectory.length + 1)
      );
      const extension = extname(relativePath).toLowerCase();
      const fileName = basename(relativePath).toLowerCase();

      if (fileName === CONTROL_FILE_NAME) {
        entries.push(await this.createControlEntry(collection, relativePath, absolutePath));
        continue;
      }

      if (collection === "assets") {
        entries.push(await this.createAssetEntry(relativePath, absolutePath));
        continue;
      }

      if (
        (collection === "docs" ||
          collection === "pages" ||
          collection === "blog" ||
          isNamedCollection(collection)) &&
        MARKDOWN_EXTENSIONS.has(extension)
      ) {
        entries.push(
          await this.createMarkdownEntry(collection, relativePath, absolutePath)
        );
        continue;
      }

      if (collection === "api" && API_EXTENSIONS.has(extension)) {
        entries.push(await this.createApiEntry(relativePath, absolutePath));
      }
    }

    return entries;
  }

  private async createMarkdownEntry(
    collection: DocsCollection,
    relativePath: string,
    absolutePath: string
  ): Promise<DocsSourceEntry> {
    const fileBuffer = await readFile(absolutePath);
    const rawText = fileBuffer.toString("utf8");
    const parsed = matter(rawText);
    const fileStats = await stat(absolutePath);
    const derivedTitle = this.deriveTitleFromPath(relativePath);

    return {
      id: createSourceEntryId(collection, relativePath),
      collection,
      relativePath,
      absolutePath,
      entryType: "content",
      body: parsed.content,
      frontmatter: {
        title: derivedTitle,
        ...parsed.data,
      },
      bytes: fileBuffer.byteLength,
      sha256: createHash("sha256").update(fileBuffer).digest("hex"),
      updatedAt: fileStats.mtime.toISOString(),
      meta: {
        extension: extname(relativePath).toLowerCase(),
      },
    };
  }

  private async createControlEntry(
    collection: DocsCollection,
    relativePath: string,
    absolutePath: string
  ): Promise<DocsSourceEntry> {
    const fileBuffer = await readFile(absolutePath);
    const rawText = fileBuffer.toString("utf8");
    const fileStats = await stat(absolutePath);

    let parsed: unknown = null;
    try {
      parsed = JSON.parse(rawText);
    } catch {
      parsed = null;
    }

    return {
      id: createSourceEntryId(collection, relativePath),
      collection,
      relativePath,
      absolutePath,
      entryType: "control",
      body: rawText,
      frontmatter: {},
      bytes: fileBuffer.byteLength,
      sha256: createHash("sha256").update(fileBuffer).digest("hex"),
      updatedAt: fileStats.mtime.toISOString(),
      meta: {
        controlFile: true,
        parsed,
      },
    };
  }

  private async createApiEntry(
    relativePath: string,
    absolutePath: string
  ): Promise<DocsSourceEntry> {
    const fileBuffer = await readFile(absolutePath);
    const fileStats = await stat(absolutePath);
    return {
      id: createSourceEntryId("api", relativePath),
      collection: "api",
      relativePath,
      absolutePath,
      entryType: "content",
      body: fileBuffer.toString("utf8"),
      frontmatter: {
        title: this.deriveTitleFromPath(relativePath),
      },
      bytes: fileBuffer.byteLength,
      sha256: createHash("sha256").update(fileBuffer).digest("hex"),
      updatedAt: fileStats.mtime.toISOString(),
      meta: {
        extension: extname(relativePath).toLowerCase(),
      },
    };
  }

  private async createAssetEntry(
    relativePath: string,
    absolutePath: string
  ): Promise<DocsSourceEntry> {
    const fileBuffer = await readFile(absolutePath);
    const fileStats = await stat(absolutePath);
    return {
      id: createSourceEntryId("assets", relativePath),
      collection: "assets",
      relativePath,
      absolutePath,
      entryType: "asset",
      frontmatter: {},
      bytes: fileBuffer.byteLength,
      sha256: createHash("sha256").update(fileBuffer).digest("hex"),
      updatedAt: fileStats.mtime.toISOString(),
      meta: {
        extension: extname(relativePath).toLowerCase(),
      },
    };
  }

  private deriveTitleFromPath(relativePath: string): string {
    const fileName = basename(relativePath).replace(/\.[^/.]+$/, "");
    return fileName
      .split(/[-_]/g)
      .map((segment) =>
        segment.length > 0
          ? `${segment.charAt(0).toUpperCase()}${segment.slice(1)}`
          : segment
      )
      .join(" ");
  }

  private createEntryInvalidError(message: string, absolutePath: string) {
    return createDocsError({
      code: "DOCS_ENTRY_INVALID",
      message,
      diagnostics: [
        createDiagnostic({
          code: "DOCS_ENTRY_INVALID",
          message,
          location: { absolutePath },
        }),
      ],
    });
  }
}
import { mkdtemp, mkdir, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { createDefaultDocsConfig, type DocsConfig } from "@docsfn/core";
import { afterEach, describe, expect, it } from "vitest";
import { FsContentProvider } from "./index";

const tempDirs: string[] = [];

afterEach(async () => {
  await Promise.all(
    tempDirs.map(async (directory) => {
      await rm(directory, { recursive: true, force: true });
    })
  );
  tempDirs.length = 0;
});

async function createTempRoot(): Promise<string> {
  const directory = await mkdtemp(join(tmpdir(), "docsfn-provider-fs-"));
  tempDirs.push(directory);
  return directory;
}

function createConfig(root: string, overrides: Partial<DocsConfig> = {}): DocsConfig {
  const defaults = createDefaultDocsConfig({ cwd: root });
  return {
    ...defaults,
    ...overrides,
    content: {
      ...defaults.content,
      ...(overrides.content ?? {}),
      root,
    },
  };
}

describe("FsContentProvider", () => {
  it("loads docs/pages/blog/api/assets and preserves meta.json as control entry", async () => {
    const root = await createTempRoot();
    await mkdir(join(root, "content/docs"), { recursive: true });
    await mkdir(join(root, "pages"), { recursive: true });
    await mkdir(join(root, "blog"), { recursive: true });
    await mkdir(join(root, "api"), { recursive: true });
    await mkdir(join(root, "public"), { recursive: true });

    await writeFile(join(root, "content/docs/meta.json"), '{"title":"Docs"}\n');
    await writeFile(
      join(root, "content/docs/index.mdx"),
      "---\ntitle: Home\n---\n\n# Home\n"
    );
    await writeFile(join(root, "pages/changelog.mdx"), "# Changelog\n");
    await writeFile(join(root, "blog/post-1.mdx"), "# Post\n");
    await writeFile(join(root, "api/openapi.yaml"), "openapi: 3.0.0\n");
    await writeFile(join(root, "public/diagram.png"), Buffer.from([0, 1, 2]));

    const provider = new FsContentProvider({ root });
    const entries = await provider.listEntries({
      config: createConfig(root),
      collections: ["docs", "pages", "blog", "api", "assets"],
    });

    const docsEntries = entries.filter((entry) => entry.collection === "docs");
    const pageEntries = entries.filter((entry) => entry.collection === "pages");
    const blogEntries = entries.filter((entry) => entry.collection === "blog");
    const apiEntries = entries.filter((entry) => entry.collection === "api");
    const assetEntries = entries.filter((entry) => entry.collection === "assets");
    const controlEntries = entries.filter((entry) => entry.entryType === "control");

    expect(docsEntries.some((entry) => entry.relativePath === "index.mdx")).toBe(true);
    expect(pageEntries.some((entry) => entry.relativePath === "changelog.mdx")).toBe(true);
    expect(blogEntries.some((entry) => entry.relativePath === "post-1.mdx")).toBe(true);
    expect(apiEntries.some((entry) => entry.relativePath === "openapi.yaml")).toBe(true);
    expect(assetEntries.some((entry) => entry.relativePath === "diagram.png")).toBe(true);
    expect(controlEntries.some((entry) => entry.relativePath === "meta.json")).toBe(true);
  });

  it("does not expose meta.json as a page in legacy list output", async () => {
    const root = await createTempRoot();
    await mkdir(join(root, "content/docs"), { recursive: true });
    await writeFile(join(root, "content/docs/meta.json"), '{"title":"Docs"}\n');
    await writeFile(join(root, "content/docs/getting-started.mdx"), "# Getting Started\n");

    const provider = new FsContentProvider({ root });
    const legacyEntries = await provider.list();

    expect(legacyEntries.some((entry) => entry.id === "meta.json")).toBe(false);
    expect(legacyEntries.some((entry) => entry.id === "getting-started.mdx")).toBe(true);
  });

  it("loads configured dated collections from their own directories", async () => {
    const root = await createTempRoot();
    await mkdir(join(root, "content/docs"), { recursive: true });
    await mkdir(join(root, "content/changelog"), { recursive: true });
    await writeFile(join(root, "content/docs/index.mdx"), "# Home\n");
    await writeFile(
      join(root, "content/changelog/release.mdx"),
      "---\ntitle: Release\ndate: 2026-03-01\n---\n\n# Release\n"
    );

    const provider = new FsContentProvider({ root });
    const changelogCollection = "collection:changelog" as const;
    const entries = await provider.listEntries({
      config: createConfig(root, {
        collections: {
          changelog: {
            dir: "content/changelog",
            routeBase: "/changelog",
          },
        },
      }),
      collections: ["docs", changelogCollection],
    });

    const changelogEntry = entries.find(
      (entry) => entry.collection === changelogCollection
    );
    expect(changelogEntry).toMatchObject({
      id: "collection:changelog:release.mdx",
      collection: changelogCollection,
      relativePath: "release.mdx",
      entryType: "content",
    });
    expect(changelogEntry?.frontmatter.title).toBe("Release");
  });

  it("assigns missing frontmatter title defaults", async () => {
    const root = await createTempRoot();
    await mkdir(join(root, "content/docs"), { recursive: true });
    await writeFile(join(root, "content/docs/no-frontmatter.mdx"), "# Title\n");

    const provider = new FsContentProvider({ root });
    const entries = await provider.listEntries({
      config: createConfig(root),
      collections: ["docs"],
    });
    const entry = entries.find((value) => value.relativePath === "no-frontmatter.mdx");

    expect(entry).toBeDefined();
    expect(entry?.frontmatter.title).toBe("No Frontmatter");
  });

  it("loads multiple docs directories and lets later directories override shared pages", async () => {
    const root = await createTempRoot();
    await mkdir(join(root, "common/docs"), { recursive: true });
    await mkdir(join(root, "product/docs"), { recursive: true });
    await writeFile(join(root, "common/docs/shared.mdx"), "# Shared from common\n");
    await writeFile(join(root, "common/docs/override.mdx"), "# Override from common\n");
    await writeFile(join(root, "product/docs/override.mdx"), "# Override from product\n");
    await writeFile(join(root, "product/docs/product-only.mdx"), "# Product only\n");

    const provider = new FsContentProvider({ root });
    const entries = await provider.listEntries({
      config: createConfig(root, {
        content: {
          root,
          docsDir: ["common/docs", "product/docs"],
        },
      }),
      collections: ["docs"],
    });

    expect(entries.map((entry) => entry.relativePath)).toEqual([
      "override.mdx",
      "product-only.mdx",
      "shared.mdx",
    ]);
    expect(entries.find((entry) => entry.relativePath === "override.mdx")?.body).toContain(
      "Override from product"
    );
    expect(entries.find((entry) => entry.relativePath === "shared.mdx")?.body).toContain(
      "Shared from common"
    );
  });

  it("ignores unsupported extensions for docs collection", async () => {
    const root = await createTempRoot();
    await mkdir(join(root, "content/docs"), { recursive: true });
    await writeFile(join(root, "content/docs/ignored.txt"), "ignore\n");
    await writeFile(join(root, "content/docs/kept.mdx"), "# Keep\n");

    const provider = new FsContentProvider({ root });
    const entries = await provider.listEntries({
      config: createConfig(root),
      collections: ["docs"],
    });

    expect(entries.some((entry) => entry.relativePath === "ignored.txt")).toBe(false);
    expect(entries.some((entry) => entry.relativePath === "kept.mdx")).toBe(true);
  });

  it("throws DOCS_ENTRY_INVALID when configured docsDir is missing", async () => {
    const root = await createTempRoot();
    const provider = new FsContentProvider({ root });
    const config = createConfig(root, {
      content: {
        root,
        docsDir: "content/missing-docs",
      },
    });

    await expect(
      provider.listEntries({
        config,
        collections: ["docs"],
      })
    ).rejects.toMatchObject({
      code: "DOCS_ENTRY_INVALID",
    });
  });

  it("throws DOCS_ENTRY_INVALID for unreadable/missing provider roots", async () => {
    const root = join(await createTempRoot(), "missing-root");
    const provider = new FsContentProvider({ root });
    const config = createConfig(root);

    await expect(
      provider.listEntries({
        config,
        collections: ["docs"],
      })
    ).rejects.toMatchObject({
      code: "DOCS_ENTRY_INVALID",
    });
  });

  it("emits deterministic ordering regardless of filesystem creation order", async () => {
    const root = await createTempRoot();
    await mkdir(join(root, "content/docs"), { recursive: true });
    await writeFile(join(root, "content/docs/zeta.mdx"), "# Zeta\n");
    await writeFile(join(root, "content/docs/alpha.mdx"), "# Alpha\n");

    const provider = new FsContentProvider({ root });
    const entries = await provider.listEntries({
      config: createConfig(root),
      collections: ["docs"],
    });

    expect(entries.map((entry) => entry.id)).toEqual([
      "docs:alpha.mdx",
      "docs:zeta.mdx",
    ]);
  });
});
import { mkdtemp, rm, writeFile } from "node:fs/promises";
