          paths: {
            "/one": {
              get: {
                operationId: "duplicateOp",
                responses: { "200": { description: "ok" } },
              },
            },
            "/two": {
              post: {
                operationId: "duplicateOp",
                responses: { "200": { description: "ok" } },
              },
            },
          },
        }),
      })
    ).toThrowError(/DOCS_OPENAPI_PARSE_FAILED|duplicate operationId/);
  });

  it("throws DOCS_OPENAPI_PARSE_FAILED for malformed path operations", () => {
    expect(() =>
      createReference({
        sourceId: "api:bad.json",
        sourcePath: "bad.json",
        body: JSON.stringify({
          openapi: "3.0.3",
