function createConfig(root: string, overrides: Partial<DocsConfig> = {}): DocsConfig {
  const defaults = createDefaultDocsConfig({ cwd: root });
  return {
    ...defaults,
    ...overrides,
    content: {
      ...defaults.content,
      ...(overrides.content ?? {}),
      root,
    },
  };
}

