import { describe, expect, it } from "vitest";
import {
  assertCompiledContentTrusted,
  assertDocsRouteAccess,
  assertSourceEntriesTrusted,
  redactSensitivePayload,
  resolveDocsAuthMode,
} from "./security";
import type { DocsSourceEntry } from "./provider";

function createEntry(overrides: Partial<DocsSourceEntry> = {}): DocsSourceEntry {
  return {
    id: "docs:index.mdx",
    collection: "docs",
    relativePath: "index.mdx",
    entryType: "content",
    frontmatter: {},
    body: "# Hello",
    ...overrides,
  };
}

describe("security", () => {
  it("blocks unsafe html in source entries by default (TV-SEC-001)", () => {
    expect(() =>
      assertSourceEntriesTrusted({
        entries: [
          createEntry({
            id: "docs:private.mdx",
            relativePath: "private.mdx",
            body: "# Unsafe\n\n<script>alert(1)</script>",
          }),
        ],
      })
    ).toThrowError(/DOCS_HTML_UNSAFE|unsafe HTML/);
  });

  it("allows explicit unsafe-html allowlist matches", () => {
    expect(() =>
      assertSourceEntriesTrusted({
        entries: [
          createEntry({
            id: "docs:legacy/unsafe.mdx",
            relativePath: "legacy/unsafe.mdx",
            body: "# Legacy\n\n<script>alert(1)</script>",
          }),
        ],
        policy: {
          allowUnsafeHtmlAllowlist: ["docs:legacy/unsafe.mdx"],
        },
      })
    ).not.toThrow();
  });

  it("ignores unsafe-looking html when it appears inside fenced code samples", () => {
    expect(() =>
      assertSourceEntriesTrusted({
        entries: [
          createEntry({
            id: "docs:guide/code-sample.mdx",
            relativePath: "guide/code-sample.mdx",
            body: [
              "# Guide",
              "",
              "```html",
              "<script>alert(1)</script>",
              "```",
              "",
              "Use `onClick=` only inside examples.",
            ].join("\n"),
          }),
        ],
      })
    ).not.toThrow();
  });

  it("applies the same trust model for compiled content artifacts", () => {
    expect(() =>
      assertCompiledContentTrusted({
        source: "# Unsafe\n\n<script>alert(1)</script>",
        sourcePath: "content/docs/unsafe.mdx",
      })
    ).toThrowError(/DOCS_HTML_UNSAFE|unsafe HTML/);
  });

  it("resolves canonical auth mode defaults", () => {
    expect(resolveDocsAuthMode({ auth: undefined })).toBe("public");
    expect(resolveDocsAuthMode({ auth: { enabled: true, mode: "private" } })).toBe(
      "private"
    );
    expect(resolveDocsAuthMode({ auth: { enabled: true, mode: "mixed" } })).toBe(
      "mixed"
    );
  });

  it("fails private routes with DOCS_AUTH_REQUIRED when no session is provided (TV-SEC-001)", async () => {
    await expect(
      assertDocsRouteAccess({
        config: {
          auth: {
            enabled: true,
            mode: "private",
          },
        },
        route: "/docs/private",
        session: null,
      })
    ).rejects.toThrowError(/DOCS_AUTH_REQUIRED|authentication is required/);
  });

  it("fails private routes with DOCS_AUTH_FORBIDDEN when authorization denies", async () => {
    await expect(
      assertDocsRouteAccess({
        config: {
          auth: {
            enabled: true,
            mode: "private",
          },
        },
        route: "/docs/private",
        session: { userId: "u_1" },
        authorize: () => false,
      })
    ).rejects.toThrowError(/DOCS_AUTH_FORBIDDEN|forbidden/);
  });

  it("treats mixed mode as private by default when route classifier is missing (fail-closed)", async () => {
    await expect(
      assertDocsRouteAccess({
        config: {
          auth: {
            enabled: true,
            mode: "mixed",
          },
        },
        route: "/docs/public",
        session: null,
      })
    ).rejects.toThrowError(/DOCS_AUTH_REQUIRED|authentication is required/);
  });

  it("allows mixed mode public routes when classifier returns false", async () => {
    await expect(
      assertDocsRouteAccess({
        config: {
          auth: {
            enabled: true,
            mode: "mixed",
          },
        },
        route: "/docs/public",
        session: null,
        isRoutePrivate: () => false,
      })
    ).resolves.toMatchObject({
      allowed: true,
      requiresAuth: false,
      mode: "mixed",
    });
  });

  it("redacts sensitive payload values and keys", () => {
    const redacted = redactSensitivePayload({
      route: "/docs",
      authorization: "Bearer abc.def.ghi",
      nested: {
        token: "sk_test_12345",
        regular: "safe-value",
      },
    });

    expect(redacted).toEqual({
      route: "/docs",
      authorization: "[REDACTED]",
      nested: {
        token: "[REDACTED]",
        regular: "safe-value",
      },
    });
  });
});
import { describe, expect, it } from "vitest";
import {
  buildOpenApiReference,
  resolveOpenApiRoute,
  type CanonicalOpenApiReference,
} from "./openapi";

function createJsonSpec(): string {
  return JSON.stringify(
    {
      openapi: "3.0.3",
      info: {
        title: "Core API",
        version: "1.0.0",
        description: "Core endpoints",
      },
      tags: [{ name: "core", description: "Core routes" }],
      paths: {
        "/search": {
          get: {
            tags: ["core"],
            summary: "Search documents",
            responses: {
              "200": {
                description: "ok",
              },
            },
          },
        },
        "/index": {
          post: {
            tags: ["core"],
            summary: "Index document",
            requestBody: {
              required: true,
              content: {
                "application/json": {
                  example: { id: "doc_1" },
                },
              },
            },
            responses: {
              "202": {
                description: "accepted",
              },
            },
          },
        },
      },
      components: {
        schemas: {
          IndexRequest: {
            type: "object",
            description: "Index payload",
          },
        },
      },
      servers: [{ url: "https://api.example.com" }],
    },
    null,
    2
  );
}

function createYamlSpec(): string {
  return [
    "openapi: 3.0.3",
    "info:",
    "  title: Admin API",
    "  version: 1.0.0",
    "  description: Admin endpoints",
    "paths:",
    "  /health:",
    "    get:",
    "      operationId: getHealth",
    "      tags:",
    "        - admin",
    "      summary: Health check",
    "      responses:",
    "        \"200\":",
    "          description: ok",
    "components:",
    "  schemas:",
    "    HealthStatus:",
    "      type: object",
    "      description: Health state",
  ].join("\n");
}

function createReference(input: {
  sourceId: string;
  sourcePath: string;
  body: string;
}): CanonicalOpenApiReference {
  return buildOpenApiReference({
    sourceId: input.sourceId,
    sourcePath: input.sourcePath,
    body: input.body,
    fallbackTitle: "Fallback API",
    basePath: "/docs",
  });
}

describe("OpenAPI normalization", () => {
  it("normalizes JSON and YAML sources into canonical operations/tags/schemas (TV-API-001)", () => {
    const jsonReference = createReference({
      sourceId: "api:core.json",
      sourcePath: "core.json",
      body: createJsonSpec(),
    });

    const yamlReference = createReference({
      sourceId: "api:admin.yaml",
      sourcePath: "admin.yaml",
      body: createYamlSpec(),
    });

    expect(jsonReference.sourceFormat).toBe("json");
    expect(jsonReference.tags.map((tag) => tag.name)).toEqual(["core"]);
    expect(
      jsonReference.operations.map((operation) => `${operation.method} ${operation.path}`)
    ).toEqual(["GET /search", "POST /index"]);

    expect(yamlReference.sourceFormat).toBe("yaml");
    expect(yamlReference.tags.map((tag) => tag.name)).toEqual(["admin"]);
    expect(
      yamlReference.operations.map((operation) => `${operation.method} ${operation.path}`)
    ).toEqual(["GET /health"]);
  });

  it("builds deterministic canonical output for equivalent specs (DET-001)", () => {
    const specA = {
      openapi: "3.0.3",
      info: { title: "Search API", version: "1.0.0" },
      paths: {
        "/b": {
          get: {
            responses: {
              "200": { description: "ok" },
            },
          },
        },
        "/a": {
          post: {
            responses: {
              "202": { description: "accepted" },
            },
          },
        },
      },
    };
    const specB = {
      ...specA,
      paths: {
        "/a": specA.paths["/a"],
        "/b": specA.paths["/b"],
      },
    };

    const referenceA = createReference({
      sourceId: "api:index-a.json",
      sourcePath: "index.json",
      body: JSON.stringify(specA),
    });
    const referenceB = createReference({
      sourceId: "api:index-a.json",
      sourcePath: "index.json",
      body: JSON.stringify(specB),
    });

    expect(JSON.stringify(referenceA)).toBe(JSON.stringify(referenceB));
  });

  it("derives overview, tag, and operation routes from normalized API records (TV-API-002)", () => {
    const reference = createReference({
      sourceId: "api:index.json",
      sourcePath: "index.json",
      body: createJsonSpec(),
    });

    expect(reference.routes.overview).toBe("/docs/api");
    expect(reference.routes.tags.core).toBe("/docs/api/tags/core");
    expect(reference.routes.all).toContain("/docs/api/operations/post-index");

    const resolved = resolveOpenApiRoute(reference, "/docs/api/operations/post-index");
    expect(resolved.kind).toBe("operation");
  });

  it("throws DOCS_OPENAPI_PARSE_FAILED for malformed YAML input (TV-API-001 negative)", () => {
    expect(() =>
      createReference({
        sourceId: "api:admin.yaml",
        sourcePath: "admin.yaml",
        body: "openapi: 3.0.3\npaths:\n  /health: [",
      })
    ).toThrowError(/DOCS_OPENAPI_PARSE_FAILED|could not be parsed/);
  });

  it("throws DOCS_OPENAPI_PARSE_FAILED for unsupported OpenAPI versions", () => {
    expect(() =>
      createReference({
        sourceId: "api:swagger.json",
        sourcePath: "swagger.json",
        body: JSON.stringify({
          swagger: "2.0",
          info: { title: "Legacy", version: "1.0.0" },
          paths: {},
        }),
      })
    ).toThrowError(/DOCS_OPENAPI_PARSE_FAILED|unsupported OpenAPI version/);
  });

  it("throws DOCS_OPENAPI_PARSE_FAILED for duplicate operation IDs", () => {
    expect(() =>
      createReference({
        sourceId: "api:dup.json",
        sourcePath: "dup.json",
        body: JSON.stringify({
          openapi: "3.0.3",
          info: { title: "Dup", version: "1.0.0" },
          paths: {
            "/one": {
              get: {
                operationId: "duplicateOp",
                responses: { "200": { description: "ok" } },
              },
            },
            "/two": {
              post: {
                operationId: "duplicateOp",
                responses: { "200": { description: "ok" } },
              },
            },
          },
        }),
      })
    ).toThrowError(/DOCS_OPENAPI_PARSE_FAILED|duplicate operationId/);
  });

  it("throws DOCS_OPENAPI_PARSE_FAILED for malformed path operations", () => {
    expect(() =>
      createReference({
        sourceId: "api:bad.json",
        sourcePath: "bad.json",
        body: JSON.stringify({
          openapi: "3.0.3",
          info: { title: "Bad", version: "1.0.0" },
          paths: {
            "/broken": {
              get: "not-an-object",
            },
          },
        }),
      })
    ).toThrowError(/DOCS_OPENAPI_PARSE_FAILED|malformed GET \/broken operation/);
  });

  it("throws DOCS_ROUTE_NOT_FOUND when resolving a missing API route (TV-API-002 negative)", () => {
    const reference = createReference({
      sourceId: "api:index.json",
      sourcePath: "index.json",
      body: createJsonSpec(),
    });

    expect(() => resolveOpenApiRoute(reference, "/docs/api/operations/get-missing")).toThrowError(
      /DOCS_ROUTE_NOT_FOUND|was not generated/
    );
  });
});
