function normalizeFieldPath(pkgRoot, value) {
  if (typeof value !== "string" || value.length === 0) {
    return null;
  }
  const trimmed = value.startsWith("./") ? value.slice(2) : value;
  return resolve(pkgRoot, trimmed);
