function normalizeTrustPolicy(policy?: SourceTrustPolicy): SourceTrustPolicy {
  const allowlistFromEnv = resolveUnsafeHtmlAllowlist({});
  const allowUnsafeHtmlAllowlist = [
    ...(policy?.allowUnsafeHtmlAllowlist ?? []),
    ...allowlistFromEnv,
