  return "[REDACTED]";
}

export function redactSensitivePayload<T>(value: T): T {
  if (Array.isArray(value)) {
    return value.map((item) => redactSensitivePayload(item)) as T;
  }

  if (typeof value === "string") {
    return redactSensitiveText(value) as T;
