        absolutePath.slice(absoluteDirectory.length + 1)
      );
      const extension = extname(relativePath).toLowerCase();
      const fileName = basename(relativePath).toLowerCase();

      if (fileName === CONTROL_FILE_NAME) {
        entries.push(await this.createControlEntry(collection, relativePath, absolutePath));
        continue;
      }

      if (collection === "assets") {
        entries.push(await this.createAssetEntry(relativePath, absolutePath));
        continue;
      }

      if (
        (collection === "docs" ||
          collection === "pages" ||
          collection === "blog" ||
          isNamedCollection(collection)) &&
        MARKDOWN_EXTENSIONS.has(extension)
      ) {
        entries.push(
          await this.createMarkdownEntry(collection, relativePath, absolutePath)
        );
        continue;
      }

      if (collection === "api" && API_EXTENSIONS.has(extension)) {
        entries.push(await this.createApiEntry(relativePath, absolutePath));
      }
    }

    return entries;
  }

  private async createMarkdownEntry(
    collection: DocsCollection,
    relativePath: string,
    absolutePath: string
  ): Promise<DocsSourceEntry> {
    const fileBuffer = await readFile(absolutePath);
    const rawText = fileBuffer.toString("utf8");
    const parsed = matter(rawText);
    const fileStats = await stat(absolutePath);
    const derivedTitle = this.deriveTitleFromPath(relativePath);

    return {
      id: createSourceEntryId(collection, relativePath),
      collection,
      relativePath,
      absolutePath,
      entryType: "content",
      body: parsed.content,
      frontmatter: {
        title: derivedTitle,
        ...parsed.data,
      },
      bytes: fileBuffer.byteLength,
      sha256: createHash("sha256").update(fileBuffer).digest("hex"),
      updatedAt: fileStats.mtime.toISOString(),
      meta: {
        extension: extname(relativePath).toLowerCase(),
      },
    };
  }

  private async createControlEntry(
    collection: DocsCollection,
    relativePath: string,
    absolutePath: string
  ): Promise<DocsSourceEntry> {
    const fileBuffer = await readFile(absolutePath);
    const rawText = fileBuffer.toString("utf8");
    const fileStats = await stat(absolutePath);

    let parsed: unknown = null;
    try {
      parsed = JSON.parse(rawText);
    } catch {
      parsed = null;
    }

    return {
      id: createSourceEntryId(collection, relativePath),
      collection,
      relativePath,
      absolutePath,
      entryType: "control",
      body: rawText,
      frontmatter: {},
      bytes: fileBuffer.byteLength,
      sha256: createHash("sha256").update(fileBuffer).digest("hex"),
      updatedAt: fileStats.mtime.toISOString(),
      meta: {
        controlFile: true,
        parsed,
      },
    };
  }

  private async createApiEntry(
    relativePath: string,
    absolutePath: string
  ): Promise<DocsSourceEntry> {
    const fileBuffer = await readFile(absolutePath);
    const fileStats = await stat(absolutePath);
    return {
      id: createSourceEntryId("api", relativePath),
      collection: "api",
      relativePath,
      absolutePath,
      entryType: "content",
      body: fileBuffer.toString("utf8"),
      frontmatter: {
        title: this.deriveTitleFromPath(relativePath),
      },
      bytes: fileBuffer.byteLength,
      sha256: createHash("sha256").update(fileBuffer).digest("hex"),
      updatedAt: fileStats.mtime.toISOString(),
      meta: {
        extension: extname(relativePath).toLowerCase(),
      },
    };
  }

  private async createAssetEntry(
    relativePath: string,
    absolutePath: string
  ): Promise<DocsSourceEntry> {
    const fileBuffer = await readFile(absolutePath);
    const fileStats = await stat(absolutePath);
    return {
      id: createSourceEntryId("assets", relativePath),
      collection: "assets",
      relativePath,
      absolutePath,
      entryType: "asset",
      frontmatter: {},
      bytes: fileBuffer.byteLength,
      sha256: createHash("sha256").update(fileBuffer).digest("hex"),
      updatedAt: fileStats.mtime.toISOString(),
      meta: {
        extension: extname(relativePath).toLowerCase(),
      },
    };
  }

  private deriveTitleFromPath(relativePath: string): string {
    const fileName = basename(relativePath).replace(/\.[^/.]+$/, "");
    return fileName
      .split(/[-_]/g)
      .map((segment) =>
        segment.length > 0
          ? `${segment.charAt(0).toUpperCase()}${segment.slice(1)}`
          : segment
      )
      .join(" ");
  }

  private createEntryInvalidError(message: string, absolutePath: string) {
    return createDocsError({
      code: "DOCS_ENTRY_INVALID",
      message,
      diagnostics: [
        createDiagnostic({
          code: "DOCS_ENTRY_INVALID",
          message,
          location: { absolutePath },
        }),
      ],
    });
  }
}

    try {
      manifest = await buildManifest(provider, config);
    } catch (error) {
      diagnostics.push(
        ...diagnosticsFromUnknownError(error, {
          code: "DOCS_ARTIFACT_INVALID",
          message: "failed to build docs manifest",
        })
      );
    }

    if (manifest) {
      try {
        searchArtifact = await buildSearchIndex(manifest, {
          search: config.search,
          auth: config.auth,
        });
      } catch (error) {
        diagnostics.push(
          ...diagnosticsFromUnknownError(error, {
            code: "DOCS_SEARCH_BUILD_FAILED",
            message: "search artifact build failed",
          })
        );
      }
    }
  }

  const invalidatedPaths = computeInvalidatedPaths({
    cwd: input.cwd,
    config,
    changedPaths: input.changedPaths,
  });

  if (invalidatedPaths.length > 0) {
    diagnostics.push(
      createDiagnostic({
        code: "DOCS_ARTIFACT_INVALID",
        severity: "info",
        message: `dev rebuild invalidated ${invalidatedPaths.length} path(s)`,
        details: {
          invalidatedPaths,
        },
      })
    );
  }

  const finalizedDiagnostics = stableSortDiagnostics(redactDiagnostics(diagnostics));
  const preset = config?.compat?.preset ?? "none";

  return {
    cwd: input.cwd,
    config,
    manifest,
    searchArtifact,
    diagnostics: finalizedDiagnostics,
    compatReport: createCompatReport({
      preset,
      diagnostics: finalizedDiagnostics,
    }),
    invalidatedPaths,
  };
}

async function writeArtifacts(outDir: string, result: PipelineResult): Promise<void> {
  await fs.mkdir(outDir, { recursive: true });

  await fs.writeFile(
    path.join(outDir, "diagnostics.json"),
    JSON.stringify(result.diagnostics, null, 2)
  );

  await fs.writeFile(
    path.join(outDir, "compat-report.json"),
    JSON.stringify(result.compatReport, null, 2)
  );

  if (result.manifest) {
    await fs.writeFile(
      path.join(outDir, "manifest.json"),
      JSON.stringify(result.manifest, null, 2)
    );
  }

  const searchEnabled = result.config?.search?.enabled ?? true;
  if (searchEnabled && result.searchArtifact) {
    await fs.writeFile(
      path.join(outDir, "search.json"),
      JSON.stringify(result.searchArtifact, null, 2)
    );
  }
}

function printDiagnostics(diagnostics: DocsDiagnostic[]): void {
  if (diagnostics.length === 0) {
    console.log(pc.green("✔ No diagnostics reported"));
    return;
  }

  const lines = formatDiagnosticsForCli(diagnostics);
  for (let index = 0; index < diagnostics.length; index += 1) {
    const diagnostic = diagnostics[index];
    const line = lines[index] ?? "";
    const colorize =
      diagnostic.severity === "error"
        ? pc.red
        : diagnostic.severity === "warning"
          ? pc.yellow
          : pc.cyan;
    console.log(colorize(line));
  }
}

function printCommandSummary(command: string, result: PipelineResult): void {
  const total = result.diagnostics.length;
  const errors = result.diagnostics.filter((diagnostic) => diagnostic.severity === "error").length;
  const warnings = result.diagnostics.filter((diagnostic) => diagnostic.severity === "warning").length;

  console.log(
    pc.blue(
      `ℹ ${command}: ${total} diagnostic(s) (${errors} errors, ${warnings} warnings)`
    )
  );

  if (result.invalidatedPaths.length > 0) {
    console.log(
      pc.dim(
        JSON.stringify(
          {
            event: "docsfn.dev.invalidate",
            invalidated: result.invalidatedPaths,
          },
          null,
          2
        )
      )
    );
  }
}

function resolveWatchTargets(input: {
  cwd: string;
  config: DocsConfig;
  providerMetadata?: DocsProviderWatchMetadata;
  outDir: string;
}): string[] {
  const targets = new Set<string>();
  const cwd = path.resolve(input.cwd);
  const outDir = path.resolve(input.outDir);

  const configFileCandidates = [
    path.resolve(cwd, "docsfn.config.ts"),
    path.resolve(cwd, "docsfn.config.mjs"),
    path.resolve(cwd, "docsfn.config.js"),
  ];
  for (const candidate of configFileCandidates) {
    targets.add(candidate);
  }

  if (input.providerMetadata?.watchedDirectories?.length) {
    for (const directory of input.providerMetadata.watchedDirectories) {
      const resolved = path.resolve(directory);
      if (resolved === outDir || resolved.startsWith(`${outDir}${path.sep}`)) {
        continue;
      }
      targets.add(resolved);
    }
  } else {
    const directories = resolveCollectionDirectories(input.config);
    for (const directory of Object.values(directories).flat()) {
      const resolved = path.resolve(directory);
      if (resolved === outDir || resolved.startsWith(`${outDir}${path.sep}`)) {
        continue;
      }
      targets.add(resolved);
    }
  }

  return [...targets].sort(compareStrings);
}

async function runValidateCommand(
  rootArg: string | undefined,
  options: BuildCommandOptions
): Promise<void> {
  const rootValue = options.root ?? rootArg ?? ".";
  const cwd = path.resolve(rootValue);

  const result = await runPipeline({
    cwd,
    configPath: options.config,
