async function runNamedCommands(commands) {
  const results = [];
  for (const item of commands) {
    await run(item.command, item.args, {
      cwd: item.cwd ?? repoRoot,
      env: item.env,
    });
    results.push({
      id: item.id,
      command: commandToString(item.command, item.args),
    });
  }
  return results;
}

