import { describe, expect, it } from "vitest";
import {
  buildOpenApiReference,
  resolveOpenApiRoute,
  type CanonicalOpenApiReference,
} from "./openapi";

function createJsonSpec(): string {
  return JSON.stringify(
    {
      openapi: "3.0.3",
      info: {
        title: "Core API",
        version: "1.0.0",
        description: "Core endpoints",
      },
      tags: [{ name: "core", description: "Core routes" }],
      paths: {
        "/search": {
          get: {
            tags: ["core"],
            summary: "Search documents",
            responses: {
              "200": {
                description: "ok",
              },
            },
          },
        },
        "/index": {
          post: {
            tags: ["core"],
            summary: "Index document",
            requestBody: {
              required: true,
              content: {
                "application/json": {
                  example: { id: "doc_1" },
                },
              },
            },
            responses: {
              "202": {
                description: "accepted",
              },
            },
          },
        },
      },
      components: {
        schemas: {
          IndexRequest: {
            type: "object",
            description: "Index payload",
          },
        },
      },
      servers: [{ url: "https://api.example.com" }],
    },
    null,
    2
  );
}

function createYamlSpec(): string {
  return [
    "openapi: 3.0.3",
    "info:",
    "  title: Admin API",
    "  version: 1.0.0",
    "  description: Admin endpoints",
    "paths:",
    "  /health:",
    "    get:",
    "      operationId: getHealth",
    "      tags:",
    "        - admin",
    "      summary: Health check",
    "      responses:",
    "        \"200\":",
    "          description: ok",
    "components:",
    "  schemas:",
    "    HealthStatus:",
    "      type: object",
    "      description: Health state",
  ].join("\n");
}

function createReference(input: {
  sourceId: string;
  sourcePath: string;
  body: string;
}): CanonicalOpenApiReference {
  return buildOpenApiReference({
    sourceId: input.sourceId,
    sourcePath: input.sourcePath,
    body: input.body,
    fallbackTitle: "Fallback API",
    basePath: "/docs",
      },
    };
    const specB = {
      ...specA,
      paths: {
        "/a": specA.paths["/a"],
        "/b": specA.paths["/b"],
      },
    };

    const referenceA = createReference({
      sourceId: "api:index-a.json",
      sourcePath: "index.json",
      body: JSON.stringify(specA),
    });
    const referenceB = createReference({
      sourceId: "api:index-a.json",
      sourcePath: "index.json",
      body: JSON.stringify(specB),
    });

    expect(JSON.stringify(referenceA)).toBe(JSON.stringify(referenceB));
  });

  it("derives overview, tag, and operation routes from normalized API records (TV-API-002)", () => {
    const reference = createReference({
      sourceId: "api:index.json",
      sourcePath: "index.json",
      body: createJsonSpec(),
    });

    expect(reference.routes.overview).toBe("/docs/api");
    expect(reference.routes.tags.core).toBe("/docs/api/tags/core");
    expect(reference.routes.all).toContain("/docs/api/operations/post-index");

    const resolved = resolveOpenApiRoute(reference, "/docs/api/operations/post-index");
    expect(resolved.kind).toBe("operation");
  });

  it("throws DOCS_OPENAPI_PARSE_FAILED for malformed YAML input (TV-API-001 negative)", () => {
    expect(() =>
      createReference({
        sourceId: "api:admin.yaml",
        sourcePath: "admin.yaml",
        body: "openapi: 3.0.3\npaths:\n  /health: [",
      })
    ).toThrowError(/DOCS_OPENAPI_PARSE_FAILED|could not be parsed/);
  });

  it("throws DOCS_OPENAPI_PARSE_FAILED for unsupported OpenAPI versions", () => {
    expect(() =>
      createReference({
        sourceId: "api:swagger.json",
        sourcePath: "swagger.json",
        body: JSON.stringify({
          swagger: "2.0",
          info: { title: "Legacy", version: "1.0.0" },
          paths: {},
        }),
      })
    ).toThrowError(/DOCS_OPENAPI_PARSE_FAILED|unsupported OpenAPI version/);
  });

  it("throws DOCS_OPENAPI_PARSE_FAILED for duplicate operation IDs", () => {
    expect(() =>
      createReference({
        sourceId: "api:dup.json",
        sourcePath: "dup.json",
        body: JSON.stringify({
          openapi: "3.0.3",
          info: { title: "Dup", version: "1.0.0" },
          paths: {
            "/one": {
              get: {
                operationId: "duplicateOp",
                responses: { "200": { description: "ok" } },
              },
            },
            "/two": {
              post: {
                operationId: "duplicateOp",
                responses: { "200": { description: "ok" } },
              },
            },
          },
        }),
      })
    ).toThrowError(/DOCS_OPENAPI_PARSE_FAILED|duplicate operationId/);
  });

  it("throws DOCS_OPENAPI_PARSE_FAILED for malformed path operations", () => {
    expect(() =>
      createReference({
        sourceId: "api:bad.json",
        sourcePath: "bad.json",
        body: JSON.stringify({
          openapi: "3.0.3",
          info: { title: "Bad", version: "1.0.0" },
          paths: {
            "/broken": {
              get: "not-an-object",
            },
          },
        }),
      })
    ).toThrowError(/DOCS_OPENAPI_PARSE_FAILED|malformed GET \/broken operation/);
  });

  it("throws DOCS_ROUTE_NOT_FOUND when resolving a missing API route (TV-API-002 negative)", () => {
    const reference = createReference({
      sourceId: "api:index.json",
      sourcePath: "index.json",
      body: createJsonSpec(),
    });

    expect(() => resolveOpenApiRoute(reference, "/docs/api/operations/get-missing")).toThrowError(
      /DOCS_ROUTE_NOT_FOUND|was not generated/
    );
  });
});
import { mkdtemp, mkdir, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { createDefaultDocsConfig, type DocsConfig } from "@docsfn/core";
import { afterEach, describe, expect, it } from "vitest";
import { FsContentProvider } from "./index";

const tempDirs: string[] = [];

afterEach(async () => {
  await Promise.all(
    tempDirs.map(async (directory) => {
      await rm(directory, { recursive: true, force: true });
    })
  );
  tempDirs.length = 0;
});

async function createTempRoot(): Promise<string> {
  const directory = await mkdtemp(join(tmpdir(), "docsfn-provider-fs-"));
  tempDirs.push(directory);
  return directory;
}

function createConfig(root: string, overrides: Partial<DocsConfig> = {}): DocsConfig {
  const defaults = createDefaultDocsConfig({ cwd: root });
  return {
    ...defaults,
    ...overrides,
    content: {
      "product-only.mdx",
      "shared.mdx",
    ]);
    expect(entries.find((entry) => entry.relativePath === "override.mdx")?.body).toContain(
      "Override from product"
    );
    expect(entries.find((entry) => entry.relativePath === "shared.mdx")?.body).toContain(
      "Shared from common"
    );
  });

  it("ignores unsupported extensions for docs collection", async () => {
    const root = await createTempRoot();
    await mkdir(join(root, "content/docs"), { recursive: true });
    await writeFile(join(root, "content/docs/ignored.txt"), "ignore\n");
    await writeFile(join(root, "content/docs/kept.mdx"), "# Keep\n");

    const provider = new FsContentProvider({ root });
    const entries = await provider.listEntries({
      config: createConfig(root),
      collections: ["docs"],
    });

    expect(entries.some((entry) => entry.relativePath === "ignored.txt")).toBe(false);
    expect(entries.some((entry) => entry.relativePath === "kept.mdx")).toBe(true);
  });

  it("throws DOCS_ENTRY_INVALID when configured docsDir is missing", async () => {
    const root = await createTempRoot();
    const provider = new FsContentProvider({ root });
    const config = createConfig(root, {
      content: {
        root,
        docsDir: "content/missing-docs",
      },
    });

    await expect(
      provider.listEntries({
        config,
        collections: ["docs"],
      })
    ).rejects.toMatchObject({
      code: "DOCS_ENTRY_INVALID",
    });
  });

  it("throws DOCS_ENTRY_INVALID for unreadable/missing provider roots", async () => {
    const root = join(await createTempRoot(), "missing-root");
    const provider = new FsContentProvider({ root });
    const config = createConfig(root);

    await expect(
      provider.listEntries({
        config,
        collections: ["docs"],
      })
    ).rejects.toMatchObject({
      code: "DOCS_ENTRY_INVALID",
    });
  });

  it("emits deterministic ordering regardless of filesystem creation order", async () => {
    const root = await createTempRoot();
    await mkdir(join(root, "content/docs"), { recursive: true });
    await writeFile(join(root, "content/docs/zeta.mdx"), "# Zeta\n");
    await writeFile(join(root, "content/docs/alpha.mdx"), "# Alpha\n");

    const provider = new FsContentProvider({ root });
    const entries = await provider.listEntries({
      config: createConfig(root),
      collections: ["docs"],
    });

    expect(entries.map((entry) => entry.id)).toEqual([
      "docs:alpha.mdx",
      "docs:zeta.mdx",
    ]);
  });
});
