import { createDiagnostic, createDocsError } from "./diagnostics";

export const BLOCKED_HTML_TAGS = [
  "script",
  "iframe",
  "object",
  "embed",
  "link",
  "meta",
] as const;

export const BLOCKED_HTML_PATTERNS = [
  { category: "event-handler", regex: /\son[a-z]+\s*=/i },
  { category: "javascript-url", regex: /javascript\s*:/i },
] as const;

export interface SanitizeSourceInput {
  source: string;
  sourcePath?: string;
  allowRawHtml?: boolean;
}

export interface UnsafeHtmlMatch {
  category: string;
  match: string;
}

function stripCodeExamples(source: string): string {
  return source
    .replace(/```[\s\S]*?```/g, " ")
    .replace(/~~~[\s\S]*?~~~/g, " ")
    .replace(/`[^`\n]+`/g, " ");
}

export function findUnsafeHtml(source: string): UnsafeHtmlMatch[] {
  const normalizedSource = stripCodeExamples(source);
  const matches: UnsafeHtmlMatch[] = [];

  for (const tag of BLOCKED_HTML_TAGS) {
    const regex = new RegExp(`<\\s*${tag}\\b`, "i");
    const found = normalizedSource.match(regex);
    if (found) {
      matches.push({ category: `blocked-tag:${tag}`, match: found[0] });
    }
  }

  for (const pattern of BLOCKED_HTML_PATTERNS) {
    const found = normalizedSource.match(pattern.regex);
    if (found) {
      matches.push({ category: pattern.category, match: found[0] });
    }
  }

  return matches;
}

export function assertSafeSource(input: SanitizeSourceInput): void {
  if (input.allowRawHtml) {
    return;
  }

  const matches = findUnsafeHtml(input.source);
  if (matches.length === 0) {
    return;
  }

  throw createDocsError({
    code: "DOCS_HTML_UNSAFE",
    message: "unsafe HTML content is blocked by default",
    diagnostics: [
      createDiagnostic({
        code: "DOCS_HTML_UNSAFE",
        message: "unsafe HTML content is blocked by default",
        location: {
          absolutePath: input.sourcePath,
        },
        details: {
          blockedCategories: matches.map((match) => match.category),
          matches,
        },
      }),
    ],
  });
}
import type { CompiledContentArtifact, CompiledContentBlock } from "./types";

export interface ResolveMarkdownRelativeLinksInput {
  compiled: CompiledContentArtifact;
  route: string;
  sourcePath?: string;
  isIndexRoute?: boolean;
}

const HREF_ATTRIBUTE_REGEX = /(<a\b[^>]*\bhref=)(["'])([^"']+)\2/gi;
const EXTERNAL_OR_SPECIAL_HREF_REGEX = /^(?:[a-z][a-z0-9+.-]*:|\/\/|#|\/|\{)/i;

export function resolveMarkdownRelativeLinks({
  compiled,
  route,
  sourcePath,
  isIndexRoute = false,
}: ResolveMarkdownRelativeLinksInput): CompiledContentArtifact {
  const baseRoute = resolveBaseRoute(route, sourcePath, isIndexRoute);

  return {
    ...compiled,
    blocks: resolveBlocks(compiled.blocks, baseRoute),
  };
}

function resolveBlocks(
  blocks: CompiledContentBlock[],
  baseRoute: string,
): CompiledContentBlock[] {
  return blocks.map((block) => {
    if ("html" in block) {
      return {
        ...block,
        html: resolveHtmlLinks(block.html, baseRoute),
      };
    }

    if (block.type === "tabs") {
      return {
        ...block,
        tabs: block.tabs.map((tab) => ({
          ...tab,
          nodes: resolveBlocks(tab.nodes, baseRoute),
        })),
      };
    }

    if (block.type === "component") {
      return {
        ...block,
        children: resolveBlocks(block.children, baseRoute),
      };
    }

    return block;
  });
}

function resolveHtmlLinks(html: string, baseRoute: string): string {
  return html.replace(HREF_ATTRIBUTE_REGEX, (match, prefix, quote, href) => {
    if (EXTERNAL_OR_SPECIAL_HREF_REGEX.test(href)) {
      return match;
    }

    const resolvedHref = resolveHref(href, baseRoute);
    return `${prefix}${quote}${resolvedHref}${quote}`;
  });
}

function resolveHref(href: string, baseRoute: string): string {
  try {
    const resolved = new URL(href, `https://docs.local${baseRoute}/`);
    return `${resolved.pathname}${resolved.search}${resolved.hash}`;
  } catch {
    return href;
  }
}

function resolveBaseRoute(
  route: string,
  sourcePath: string | undefined,
  isIndexRoute: boolean,
): string {
  const normalizedRoute = normalizeAbsolutePath(route);

  if (isIndexRoute || (sourcePath && /(?:^|\/)index\.mdx?$/i.test(sourcePath))) {
    return normalizedRoute;
  }

  const separatorIndex = normalizedRoute.lastIndexOf("/");
  if (separatorIndex <= 0) {
    return "/";
  }

  return normalizedRoute.slice(0, separatorIndex);
}

function normalizeAbsolutePath(path: string): string {
  const prefixed = path.startsWith("/") ? path : `/${path}`;
  let end = prefixed.length;
  while (end > 1 && prefixed.charCodeAt(end - 1) === 47) end -= 1;
  return prefixed.slice(0, end);
}
import { assertValidBlogPublishMetadata, resolveBlogLastBuildDate } from "./blog";
import { normalizeDatedCollectionId } from "./provider";
import type { BlogPost, DocsManifest } from "./types";

export interface RSSFeedOptions {
  title: string;
  description: string;
  /**
   * Generate a feed for a named dated collection such as `changelog`.
   * When omitted, the legacy blog surface is used.
   */
  collectionId?: string;
  /** Public URL for the channel (often the blog index page). */
  link: string;
  language?: string;
  /**
   * Absolute URL for this feed’s `atom:link rel="self"`.
   * Default: `{link}{manifest.blog.feedPath}` when `link` has no path, or join with manifest feed path.
   */
  feedHref?: string;
  /**
   * Absolute permalink for a post. Use when public blog URLs differ from `post.path` on the manifest
   * (e.g. docs at `/docs` but the app serves posts under `/blog/[slug]`).
   */
  itemHref?: (post: BlogPost) => string;
}

/**
 * Generate RSS 2.0 feed XML from blog posts
 */
export function generateRSSFeed(
  manifest: DocsManifest,
  options: RSSFeedOptions
): string {
  const { title, description, link, language = "en" } = options;

  let linkEnd = link.length;
  while (linkEnd > 0 && link.charCodeAt(linkEnd - 1) === 47) linkEnd -= 1;
  const normalizedLink = link.slice(0, linkEnd);
  const hasRequestedCollection = options.collectionId !== undefined;
  const requestedCollectionId = hasRequestedCollection
    ? normalizeDatedCollectionId(options.collectionId ?? "")
    : undefined;
  const collectionSurface = requestedCollectionId
    ? manifest.collections?.[requestedCollectionId]
    : undefined;
  const orderedIds = hasRequestedCollection
    ? collectionSurface?.postOrder ?? []
    : manifest.blog?.postOrder ?? [];
  const orderedPostsFromManifest = orderedIds
    .map((id) => manifest.posts[id])
    .filter((post): post is BlogPost => Boolean(post));
  const fallbackPosts =
    hasRequestedCollection && !collectionSurface
      ? []
      : Object.values(manifest.posts)
          .filter(
            (post) =>
              !hasRequestedCollection ||
              normalizeDatedCollectionId(post.collectionId ?? "blog") === requestedCollectionId
          )
          .sort((left, right) => {
            const leftDate = assertValidBlogPublishMetadata(left).timestamp;
            const rightDate = assertValidBlogPublishMetadata(right).timestamp;
            if (leftDate !== rightDate) {
              return rightDate - leftDate;
            }
            return left.slug.localeCompare(right.slug, "en", {
              sensitivity: "variant",
              numeric: true,
            });
          });
  const posts =
    orderedPostsFromManifest.length > 0
      ? orderedPostsFromManifest
      : fallbackPosts;

  const items = posts
    .map((post) => {
      const publish = assertValidBlogPublishMetadata(post);
      const postLink = options.itemHref
        ? options.itemHref(post)
        : `${normalizedLink}${post.path}`;
      const descriptionValue = post.excerpt ?? post.summary;
      return `
    <item>
      <title><![CDATA[${post.title}]]></title>
      <link>${escapeXml(postLink)}</link>
      <guid isPermaLink="true">${escapeXml(postLink)}</guid>
      <pubDate>${new Date(publish.publishedAt).toUTCString()}</pubDate>
      ${descriptionValue ? `<description><![CDATA[${descriptionValue}]]></description>` : ""}
      ${post.author ? `<author>${escapeXml(post.author)}</author>` : ""}
      ${post.tags.map((tag) => `<category>${escapeXml(tag)}</category>`).join("\n      ")}
    </item>
  `;
    })
    .join("");

  const feedPath = hasRequestedCollection
    ? collectionSurface?.feedPath ?? "/rss.xml"
    : manifest.blog?.feedPath ?? "/rss.xml";
  const feedLink = options.feedHref ?? `${normalizedLink}${feedPath}`;
  const lastBuildDate = resolveBlogLastBuildDate(posts);

  return `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom">
  <channel>
    <title>${escapeXml(title)}</title>
    <description>${escapeXml(description)}</description>
    <link>${escapeXml(normalizedLink)}</link>
    <language>${escapeXml(language)}</language>
    <lastBuildDate>${lastBuildDate}</lastBuildDate>
    <atom:link href="${escapeXml(feedLink)}" rel="self" type="application/rss+xml"/>
    ${items}
  </channel>
</rss>`;
}

function escapeXml(value: string): string {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&apos;");
}
import { createDiagnostic, createDocsError } from "./diagnostics";
import type { DocsSearchArtifact, DocsSearchDocument } from "./search";
import type { DocsSearchRuntimeResultItem } from "./search-runtime";
import type {
  DocsSearchEngineAdapter,
  DocsSearchIndexEngine,
  DocsSearchRuntimeBackend,
  DocsSearchRuntimeBackendQueryInput,
} from "./search-adapter";

const SEARCHFN_PIPELINE = {
  enableEdgeNGrams: true,
  edgeNGramMinLength: 2,
};

interface SnapshotSearchEngine extends DocsSearchIndexEngine {
  importSnapshot(snapshot: DocsSearchArtifact["snapshot"]): void;
  searchDetailed(
    query: string,
    options: {
      fields?: string[];
      limit?: number;
    }
  ): Array<{ docId: string | number; score: number }>;
}

interface SearchFnClientModule {
  InMemorySearchFn: new (options: {
    fields: string[];
    pipeline?: {
      enableEdgeNGrams?: boolean;
      edgeNGramMinLength?: number;
    };
  }) => SnapshotSearchEngine;
}

async function loadSearchFnClient(
  usage: "build" | "runtime"
): Promise<SearchFnClientModule> {
  try {
    return (await import("@searchfn/client")) as unknown as SearchFnClientModule;
  } catch (error) {
    const code =
      usage === "build" ? "DOCS_SEARCH_BUILD_FAILED" : "DOCS_ARTIFACT_INVALID";
    const action = usage === "build" ? "build a docs search index" : "query a docs search artifact";
    throw createDocsError({
      code,
      message: `@searchfn/client is required to ${action}`,
      diagnostics: [
        createDiagnostic({
          code,
          message: `@searchfn/client is required to ${action}`,
          suggestion:
            usage === "build"
              ? "Install @searchfn/client, disable docs search, or provide a prebuilt search artifact."
              : "Install @searchfn/client or avoid creating the docs search runtime on pages that do not use search.",
        }),
      ],
      cause: error,
    });
  }
}

class SearchFnRuntimeBackend implements DocsSearchRuntimeBackend {
  constructor(
    private readonly artifact: DocsSearchArtifact,
    private readonly documents: Map<string, DocsSearchDocument>,
    private readonly engine: SnapshotSearchEngine
  ) {}

  async query(
    input: DocsSearchRuntimeBackendQueryInput
  ): Promise<DocsSearchRuntimeResultItem[]> {
    const engineResults = this.engine.searchDetailed(input.query, {
      fields: this.artifact.fields,
      limit: this.artifact.documents.length || Math.max(input.limit, 20),
    });

    return engineResults
      .map((hit) => {
        const document = this.documents.get(String(hit.docId));
        if (!document) {
          return null;
        }
        return {
          id: document.id,
          score: hit.score,
          scope: document.scope,
          kind: document.kind,
          path: document.path,
          title: document.title,
          summary: document.summary,
        };
      })
      .filter((item): item is DocsSearchRuntimeResultItem => item !== null)
      .filter((item) => item.path.length > 0 && item.title.length > 0)
      .filter((item) => input.scope === "all" || item.scope === input.scope);
  }
}

export const searchFnSearchAdapter: DocsSearchEngineAdapter = {
  name: "searchfn",
  async createIndexEngine(input) {
    const { InMemorySearchFn } = await loadSearchFnClient("build");
    return new InMemorySearchFn({
      fields: input.fields,
      pipeline: SEARCHFN_PIPELINE,
    });
  },
  async createRuntime(input) {
    const { InMemorySearchFn } = await loadSearchFnClient("runtime");
    const engine = new InMemorySearchFn({
      fields: input.artifact.fields,
      pipeline: SEARCHFN_PIPELINE,
    });
    engine.importSnapshot(input.artifact.snapshot);
    return new SearchFnRuntimeBackend(input.artifact, input.documents, engine);
  },
};
import { createDiagnostic, createDocsError } from "../diagnostics";

const SUPPORTED_FUMADOCS_IMPORTS: Record<string, Set<string>> = {
  "fumadocs-ui/components/tabs": new Set(["Tabs", "Tab"]),
};

export interface FumadocsTransformInput {
  source: string;
  sourcePath?: string;
}

export interface FumadocsTransformResult {
  transformed: string;
  importedComponents: Set<string>;
  componentsUsed: string[];
}

function parseImportSpecifiers(source: string): string[] {
  return source
    .split(",")
    .map((entry) => {
      const words = entry.trim().split(/\s+/);
      const alias = words.indexOf("as");
      return words.slice(0, alias === -1 ? words.length : alias).join(" ");
    })
    .filter(Boolean);
}

function parseNamedImport(line: string): { rawSpecifiers: string; moduleName: string } | null {
  const trimmed = line.trim().replace(/;$/, "").trimEnd();
  if (!trimmed.startsWith("import")) return null;
  const open = trimmed.indexOf("{");
  const close = trimmed.indexOf("}", open + 1);
  if (open === -1 || close === -1 || trimmed.slice(6, open).trim() !== "") return null;
  const from = trimmed.slice(close + 1).trim();
  if (!from.startsWith("from")) return null;
  const quoted = from.slice(4).trim();
  const quote = quoted[0];
  if ((quote !== '"' && quote !== "'") || quoted.at(-1) !== quote) return null;
  return { rawSpecifiers: trimmed.slice(open + 1, close), moduleName: quoted.slice(1, -1) };
}

function validateFumadocsImport(input: {
  sourcePath?: string;
  moduleName: string;
  specifier: string;
}): void {
  const supported = SUPPORTED_FUMADOCS_IMPORTS[input.moduleName];
  if (supported && supported.has(input.specifier)) {
    return;
  }

  throw createDocsError({
    code: "DOCS_COMPAT_UNSUPPORTED",
    message: `unsupported compatibility construct ${input.specifier} from ${input.moduleName}`,
    diagnostics: [
      createDiagnostic({
        code: "DOCS_COMPAT_UNSUPPORTED",
        message: `unsupported compatibility construct ${input.specifier} from ${input.moduleName}`,
        location: {
          absolutePath: input.sourcePath,
        },
        details: {
          component: input.specifier,
          module: input.moduleName,
        },
      }),
    ],
  });
}

function rewriteFumadocsTags(source: string): string {
  return source
    .replace(/<\s*Tabs(?=[\s>])/g, "<DocsTabs")
    .replace(/<\s*\/\s*Tabs\s*>/g, "</DocsTabs>")
    .replace(/<\s*Tab(?=[\s>])/g, "<DocsTab")
    .replace(/<\s*\/\s*Tab\s*>/g, "</DocsTab>");
}

export function transformFumadocsV15(
  input: FumadocsTransformInput
): FumadocsTransformResult {
  const lines = input.source.split(/\r?\n/);
  const keptLines: string[] = [];
  const importedComponents = new Set<string>();

  for (const line of lines) {
    const importMatch = parseNamedImport(line);
    if (!importMatch) {
      keptLines.push(line);
      continue;
    }

    const { rawSpecifiers, moduleName } = importMatch;
    const specifiers = parseImportSpecifiers(rawSpecifiers);
    for (const specifier of specifiers) {
      importedComponents.add(specifier);
      if (moduleName.startsWith("fumadocs")) {
        validateFumadocsImport({
          sourcePath: input.sourcePath,
          moduleName,
          specifier,
        });
      }
    }
  }

  const transformed = rewriteFumadocsTags(keptLines.join("\n"));
  const componentsUsed: string[] = [];

  if (/<\s*DocsTabs(?=[\s>])/.test(transformed)) {
    componentsUsed.push("DocsTabs");
  }
  if (/<\s*DocsTab(?=[\s>])/.test(transformed)) {
    componentsUsed.push("DocsTab");
  }
  if (/```mermaid/.test(transformed)) {
    componentsUsed.push("MermaidBlock");
  }

  return {
    transformed,
    importedComponents,
    componentsUsed,
  };
}

