import { createDiagnostic, createDocsError } from "./diagnostics";
import type { DocsSearchArtifact, DocsSearchDocument } from "./search";
import type { DocsSearchRuntimeResultItem } from "./search-runtime";
import type {
  DocsSearchEngineAdapter,
  DocsSearchIndexEngine,
  DocsSearchRuntimeBackend,
  DocsSearchRuntimeBackendQueryInput,
} from "./search-adapter";

const SEARCHFN_PIPELINE = {
  enableEdgeNGrams: true,
  edgeNGramMinLength: 2,
};

interface SnapshotSearchEngine extends DocsSearchIndexEngine {
  importSnapshot(snapshot: DocsSearchArtifact["snapshot"]): void;
  searchDetailed(
    query: string,
    options: {
      fields?: string[];
      limit?: number;
    }
  ): Array<{ docId: string | number; score: number }>;
}

interface SearchFnClientModule {
  InMemorySearchFn: new (options: {
    fields: string[];
    pipeline?: {
      enableEdgeNGrams?: boolean;
      edgeNGramMinLength?: number;
    };
  }) => SnapshotSearchEngine;
}

async function loadSearchFnClient(
  usage: "build" | "runtime"
): Promise<SearchFnClientModule> {
  try {
    return (await import("@searchfn/client")) as unknown as SearchFnClientModule;
  } catch (error) {
    const code =
      usage === "build" ? "DOCS_SEARCH_BUILD_FAILED" : "DOCS_ARTIFACT_INVALID";
    const action = usage === "build" ? "build a docs search index" : "query a docs search artifact";
    throw createDocsError({
      code,
      message: `@searchfn/client is required to ${action}`,
      diagnostics: [
        createDiagnostic({
          code,
          message: `@searchfn/client is required to ${action}`,
          suggestion:
            usage === "build"
              ? "Install @searchfn/client, disable docs search, or provide a prebuilt search artifact."
              : "Install @searchfn/client or avoid creating the docs search runtime on pages that do not use search.",
        }),
      ],
      cause: error,
    });
  }
}

class SearchFnRuntimeBackend implements DocsSearchRuntimeBackend {
  constructor(
    private readonly artifact: DocsSearchArtifact,
    private readonly documents: Map<string, DocsSearchDocument>,
    private readonly engine: SnapshotSearchEngine
  ) {}

  async query(
    input: DocsSearchRuntimeBackendQueryInput
  ): Promise<DocsSearchRuntimeResultItem[]> {
    const engineResults = this.engine.searchDetailed(input.query, {
      fields: this.artifact.fields,
      limit: this.artifact.documents.length || Math.max(input.limit, 20),
    });

    return engineResults
      .map((hit) => {
        const document = this.documents.get(String(hit.docId));
        if (!document) {
          return null;
        }
        return {
          id: document.id,
          score: hit.score,
          scope: document.scope,
          kind: document.kind,
          path: document.path,
          title: document.title,
          summary: document.summary,
        };
      })
      .filter((item): item is DocsSearchRuntimeResultItem => item !== null)
      .filter((item) => item.path.length > 0 && item.title.length > 0)
      .filter((item) => input.scope === "all" || item.scope === input.scope);
  }
}

export const searchFnSearchAdapter: DocsSearchEngineAdapter = {
  name: "searchfn",
  async createIndexEngine(input) {
    const { InMemorySearchFn } = await loadSearchFnClient("build");
    return new InMemorySearchFn({
      fields: input.fields,
      pipeline: SEARCHFN_PIPELINE,
    });
  },
  async createRuntime(input) {
    const { InMemorySearchFn } = await loadSearchFnClient("runtime");
    const engine = new InMemorySearchFn({
      fields: input.artifact.fields,
      pipeline: SEARCHFN_PIPELINE,
    });
    engine.importSnapshot(input.artifact.snapshot);
    return new SearchFnRuntimeBackend(input.artifact, input.documents, engine);
  },
};
import { createDiagnostic, createDocsError } from "../diagnostics";

const SUPPORTED_FUMADOCS_IMPORTS: Record<string, Set<string>> = {
  "fumadocs-ui/components/tabs": new Set(["Tabs", "Tab"]),
};

export interface FumadocsTransformInput {
  source: string;
  sourcePath?: string;
}

export interface FumadocsTransformResult {
  transformed: string;
  importedComponents: Set<string>;
  componentsUsed: string[];
}

function parseImportSpecifiers(source: string): string[] {
  return source
    .split(",")
    .map((entry) => {
      const words = entry.trim().split(/\s+/);
      const alias = words.indexOf("as");
      return words.slice(0, alias === -1 ? words.length : alias).join(" ");
    })
    .filter(Boolean);
}

function parseNamedImport(line: string): { rawSpecifiers: string; moduleName: string } | null {
  const trimmed = line.trim().replace(/;$/, "").trimEnd();
  if (!trimmed.startsWith("import")) return null;
  const open = trimmed.indexOf("{");
  const close = trimmed.indexOf("}", open + 1);
  if (open === -1 || close === -1 || trimmed.slice(6, open).trim() !== "") return null;
  const from = trimmed.slice(close + 1).trim();
  if (!from.startsWith("from")) return null;
  const quoted = from.slice(4).trim();
  const quote = quoted[0];
  if ((quote !== '"' && quote !== "'") || quoted.at(-1) !== quote) return null;
  return { rawSpecifiers: trimmed.slice(open + 1, close), moduleName: quoted.slice(1, -1) };
}

function validateFumadocsImport(input: {
  sourcePath?: string;
  moduleName: string;
  specifier: string;
}): void {
  const supported = SUPPORTED_FUMADOCS_IMPORTS[input.moduleName];
  if (supported && supported.has(input.specifier)) {
    return;
  }

  throw createDocsError({
    code: "DOCS_COMPAT_UNSUPPORTED",
    message: `unsupported compatibility construct ${input.specifier} from ${input.moduleName}`,
    diagnostics: [
      createDiagnostic({
        code: "DOCS_COMPAT_UNSUPPORTED",
        message: `unsupported compatibility construct ${input.specifier} from ${input.moduleName}`,
        location: {
          absolutePath: input.sourcePath,
        },
        details: {
          component: input.specifier,
          module: input.moduleName,
        },
      }),
    ],
  });
}

function rewriteFumadocsTags(source: string): string {
  return source
    .replace(/<\s*Tabs(?=[\s>])/g, "<DocsTabs")
    .replace(/<\s*\/\s*Tabs\s*>/g, "</DocsTabs>")
    .replace(/<\s*Tab(?=[\s>])/g, "<DocsTab")
    .replace(/<\s*\/\s*Tab\s*>/g, "</DocsTab>");
}

export function transformFumadocsV15(
  input: FumadocsTransformInput
): FumadocsTransformResult {
  const lines = input.source.split(/\r?\n/);
  const keptLines: string[] = [];
  const importedComponents = new Set<string>();

  for (const line of lines) {
    const importMatch = parseNamedImport(line);
    if (!importMatch) {
      keptLines.push(line);
      continue;
    }

    const { rawSpecifiers, moduleName } = importMatch;
    const specifiers = parseImportSpecifiers(rawSpecifiers);
    for (const specifier of specifiers) {
      importedComponents.add(specifier);
      if (moduleName.startsWith("fumadocs")) {
        validateFumadocsImport({
          sourcePath: input.sourcePath,
          moduleName,
          specifier,
        });
      }
    }
  }

  const transformed = rewriteFumadocsTags(keptLines.join("\n"));
  const componentsUsed: string[] = [];

  if (/<\s*DocsTabs(?=[\s>])/.test(transformed)) {
    componentsUsed.push("DocsTabs");
  }
  if (/<\s*DocsTab(?=[\s>])/.test(transformed)) {
    componentsUsed.push("DocsTab");
  }
  if (/```mermaid/.test(transformed)) {
    componentsUsed.push("MermaidBlock");
  }

  return {
    transformed,
    importedComponents,
    componentsUsed,
  };
}

