import path from "node:path";
import {
  buildManifest,
  buildSearchIndex,
  compileSvelteContent,
  createDiagnostic,
  createDocsError,
  createDocsSearchRuntime,
  loadDocsConfig,
  type CompiledContentArtifact,
  type DocsCompatPreset,
  type DocsConfig,
  type DocsManifest,
  type DocsSearchArtifact,
  type DocsSearchRuntime,
} from "@docsfn/core";
import { FsContentProvider } from "@docsfn/provider-fs";

export interface DocsSiteSource {
  siteRoot: string;
  manifest: DocsManifest;
  searchArtifact: DocsSearchArtifact;
  siteTitle: string;
  canonicalUrl?: string;
  compatPreset: DocsCompatPreset;
  config: DocsConfig;
}

export interface DocsSiteCompiledCacheSummary {
  framework: "svelte";
  compatPreset: DocsCompatPreset;
  pageKeys: string[];
  postKeys: string[];
}

interface DocsSiteCompiledContentCache {
  framework: "svelte";
  compatPreset: DocsCompatPreset;
  pages: Map<string, CompiledContentArtifact>;
  posts: Map<string, CompiledContentArtifact>;
  pageKeysById: Record<string, string>;
  postKeysById: Record<string, string>;
}

interface DocsSiteServerState {
  source: DocsSiteSource;
  compiledCache: DocsSiteCompiledContentCache;
}

let serverStatePromise: Promise<DocsSiteServerState> | null = null;

function shouldCacheServerState(): boolean {
  return process.env.NODE_ENV !== "development";
}

function createCompiledCacheKey(input: {
  kind: "page" | "post";
  id: string;
  framework: "svelte";
  compatPreset: DocsCompatPreset;
}): string {
  return [input.kind, input.id, input.framework, input.compatPreset].join("|");
}

function sortById<T extends { id: string }>(items: T[]): T[] {
  return [...items].sort((left, right) =>
    left.id.localeCompare(right.id, "en", {
      sensitivity: "variant",
      numeric: true,
    })
  );
}

function createCompiledCache(input: {
  manifest: DocsManifest;
  compatPreset: DocsCompatPreset;
}): DocsSiteCompiledContentCache {
  const framework = "svelte" as const;
  const pages = new Map<string, CompiledContentArtifact>();
  const posts = new Map<string, CompiledContentArtifact>();
  const pageKeysById: Record<string, string> = {};
  const postKeysById: Record<string, string> = {};

  for (const page of sortById(Object.values(input.manifest.pages))) {
    const key = createCompiledCacheKey({
      kind: "page",
      id: page.id,
      framework,
      compatPreset: input.compatPreset,
    });
    pageKeysById[page.id] = key;
    pages.set(
      key,
      compileSvelteContent({
        source: page.body,
        sourcePath: page.id,
        compatPreset: input.compatPreset,
      })
    );
  }

  for (const post of sortById(Object.values(input.manifest.posts))) {
    const key = createCompiledCacheKey({
      kind: "post",
      id: post.id,
      framework,
      compatPreset: input.compatPreset,
    });
    postKeysById[post.id] = key;
    posts.set(
      key,
      compileSvelteContent({
        source: post.body,
        sourcePath: post.id,
        compatPreset: input.compatPreset,
      })
    );
  }

  return {
    framework,
    compatPreset: input.compatPreset,
    pages,
    posts,
    pageKeysById,
    postKeysById,
  };
}

function getCompiledArtifactOrThrow(input: {
  kind: "page" | "post";
  id: string;
  cache: DocsSiteCompiledContentCache;
}): CompiledContentArtifact {
  const keysById =
    input.kind === "page" ? input.cache.pageKeysById : input.cache.postKeysById;
  const entries = input.kind === "page" ? input.cache.pages : input.cache.posts;
  const key = keysById[input.id];

  if (!key) {
    throw createDocsError({
      code: "DOCS_ARTIFACT_INVALID",
      message: `compiled ${input.kind} cache key is missing for ${input.id}`,
      diagnostics: [
        createDiagnostic({
          code: "DOCS_ARTIFACT_INVALID",
          message: `compiled ${input.kind} cache key is missing for ${input.id}`,
          details: {
            kind: input.kind,
            id: input.id,
          },
        }),
      ],
    });
  }

  const compiled = entries.get(key);
  if (!compiled) {
    throw createDocsError({
      code: "DOCS_ARTIFACT_INVALID",
      message: `compiled ${input.kind} artifact is missing for ${input.id}`,
      diagnostics: [
        createDiagnostic({
          code: "DOCS_ARTIFACT_INVALID",
          message: `compiled ${input.kind} artifact is missing for ${input.id}`,
          details: {
            kind: input.kind,
            id: input.id,
            key,
          },
        }),
      ],
    });
  }

  return compiled;
}

async function createDocsSiteServerState(): Promise<DocsSiteServerState> {
  const siteRoot = path.resolve(process.cwd());
  const config = await loadDocsConfig({ cwd: siteRoot });
  const provider = new FsContentProvider({
    root: siteRoot,
    docsDir: config.content.docsDir,
    pagesDir: config.content.pagesDir,
    blogDir: config.content.blogDir,
    apiDir: config.content.apiDir,
    assetsDir: config.content.assetsDir,
  });
  const manifest = await buildManifest(provider, config);
  const searchArtifact = await buildSearchIndex(manifest, {
    search: config.search,
    auth: config.auth,
  });
  const compatPreset = config.compat?.preset ?? "none";
  const compiledCache = createCompiledCache({
    manifest,
    compatPreset,
  });

  return {
    source: {
      siteRoot,
      manifest,
      searchArtifact,
      siteTitle: config.site.title,
      canonicalUrl: config.site.canonicalUrl,
      compatPreset,
      config,
    },
    compiledCache,
  };
}

async function loadDocsSiteServerState(): Promise<DocsSiteServerState> {
  if (!shouldCacheServerState()) {
    return createDocsSiteServerState();
  }

  if (!serverStatePromise) {
    serverStatePromise = createDocsSiteServerState();
  }

  return serverStatePromise;
}

export async function loadDocsSiteSource(): Promise<DocsSiteSource> {
  const state = await loadDocsSiteServerState();
  return state.source;
}

export async function getCompiledDocsPage(pageId: string): Promise<CompiledContentArtifact> {
  const state = await loadDocsSiteServerState();
  return getCompiledArtifactOrThrow({
    kind: "page",
    id: pageId,
    cache: state.compiledCache,
  });
}

import path from "node:path";
import { fileURLToPath } from "node:url";
import {
  buildManifest,
  buildSearchIndex,
  createDocsSearchRuntime,
  loadDocsConfig,
  type DocsCompatPreset,
  type DocsManifest,
  type DocsSearchArtifact,
} from "@docsfn/core";
import { FsContentProvider } from "@docsfn/provider-fs";

export interface DocsSiteSource {
  fixtureRoot: string;
  manifest: DocsManifest;
  searchArtifact: DocsSearchArtifact;
  searchProbe: {
    query: string;
    resultCount: number;
    firstPath?: string;
    scopes: string[];
  };
  siteTitle: string;
  canonicalUrl?: string;
  compatPreset: DocsCompatPreset;
}

const thisFilePath = fileURLToPath(import.meta.url);
const thisDirectory = path.dirname(thisFilePath);
const DEFAULT_FIXTURE_ROOT = path.resolve(
  thisDirectory,
  "../../test-fixtures/repo/searchfn-docs"
);

let sourcePromise: Promise<DocsSiteSource> | null = null;

function resolveFixtureRoot(): string {
  const override = process.env.DOCSFN_FIXTURE_ROOT;
  if (override && override.trim().length > 0) {
    return path.resolve(thisDirectory, override);
  }
  return DEFAULT_FIXTURE_ROOT;
}

async function buildSearchProbe(
  searchArtifact: DocsSearchArtifact
): Promise<DocsSiteSource["searchProbe"]> {
  const probeQuery =
    searchArtifact.documents.find((document) => document.title.trim().length > 0)?.title ??
    searchArtifact.documents[0]?.summary ??
    "docs";
  const runtime = createDocsSearchRuntime({
    artifact: searchArtifact,
  });
  const results = await runtime.query({
    query: probeQuery,
    limit: 5,
  });

  return {
    query: probeQuery,
    resultCount: results.length,
    firstPath: results[0]?.path,
    scopes: [...searchArtifact.scopes],
  };
}

export async function loadDocsSiteSource(): Promise<DocsSiteSource> {
  if (!sourcePromise) {
    sourcePromise = (async () => {
      const fixtureRoot = resolveFixtureRoot();
      const config = await loadDocsConfig({
        cwd: fixtureRoot,
      });

      const provider = new FsContentProvider({
        root: fixtureRoot,
      });
      const manifest = await buildManifest(provider, config);
      const searchArtifact = await buildSearchIndex(manifest, {
        search: config.search,
      });
      const searchProbe = await buildSearchProbe(searchArtifact);

      return {
        fixtureRoot,
        manifest,
        searchArtifact,
        searchProbe,
        siteTitle: config.site.title,
        canonicalUrl: config.site.canonicalUrl,
        compatPreset: config.compat?.preset ?? "none",
      };
    })();
  }

  return sourcePromise;
}
import { notFound } from "next/navigation";
import { EmbeddedPage as ReactEmbeddedPage } from "@docsfn/react/EmbeddedPage";
import { loadDocsSiteSource } from "@/source.config";

type EmbeddedPageParams = {
  slug?: string[];
};

export async function generateStaticParams() {
  const source = await loadDocsSiteSource();
  return Object.values(source.manifest.embedded?.pages ?? {})
    .map((entry) => {
      const suffix = entry.pageRoute
        .replace(source.manifest.embedded?.pageRoutePrefix ?? "/docs/embedded/page", "")
        .replace(/^\/+/, "");
      const segments = suffix.length > 0 ? suffix.split("/") : [];
      return {
        slug: segments,
      };
    })
    .sort((left, right) => left.slug.join("/").localeCompare(right.slug.join("/")));
}

export default async function EmbeddedPage(props: {
  params: Promise<EmbeddedPageParams>;
}) {
  const params = await props.params;
  const source = await loadDocsSiteSource();
  const requestedSlug = (params.slug ?? []).join("/");
  const normalizedSlug = requestedSlug.length > 0 ? requestedSlug : "index";

  const page = Object.values(source.manifest.pages).find((candidate) => {
    const candidateSlug = candidate.slug.length > 0 ? candidate.slug : "index";
    return candidateSlug === normalizedSlug;
  });
  if (!page) {
    notFound();
  }

  return (
    <section data-docsfn-proof-surface="embedded">
      <ReactEmbeddedPage
        page={page}
        compatPreset={source.compatPreset}
      />
    </section>
  );
}
import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { getDocsBlogPostData } from "@docsfn/next";
import { DocsContent } from "@docsfn/react/DocsContent";
import { loadDocsSiteSource } from "@/source.config";

type BlogPageParams = {
  slug: string;
};

export async function generateStaticParams() {
  const source = await loadDocsSiteSource();
  return Object.values(source.manifest.posts).map((post) => ({
    slug: post.slug,
  }));
}

export async function generateMetadata(props: {
  params: Promise<BlogPageParams>;
}): Promise<Metadata> {
  const params = await props.params;
  const source = await loadDocsSiteSource();
  const post = getDocsBlogPostData(params.slug, source.manifest);
  if (!post) {
    return {};
  }

  const canonical = source.canonicalUrl
    ? `${source.canonicalUrl.replace(/\/+$/, "")}${post.path}`
    : post.path;

  return {
    title: `${post.title} | ${source.siteTitle}`,
    description: post.excerpt ?? post.summary ?? post.title,
    alternates: {
      canonical,
    },
    openGraph: {
      title: post.title,
      description: post.excerpt ?? post.summary ?? post.title,
      url: canonical,
    },
  };
}

export default async function BlogPostPage(props: {
  params: Promise<BlogPageParams>;
}) {
  const params = await props.params;
  const source = await loadDocsSiteSource();
  const post = getDocsBlogPostData(params.slug, source.manifest);
  if (!post) {
    notFound();
  }

  return (
    <article
      className="docs-example-article"
      data-docsfn-blog-post="true"
      data-docsfn-proof-surface="blog"
    >
      <h1>{post.title}</h1>
      <p>{new Date(post.publishedAt ?? post.date).toUTCString()}</p>
      {post.author ? <p>By {post.author}</p> : null}
      {post.excerpt ?? post.summary ? <p>{post.excerpt ?? post.summary}</p> : null}
      {post.tags.length > 0 ? (
        <p>
          Tags: {post.tags.join(", ")}
        </p>
      ) : null}
      <DocsContent
        content={post.body}
        sourcePath={post.id}
        compatPreset={source.compatPreset}
      />
    </article>
  );
}
