import type { DocsConfig } from "@docsfn/core";

const config: DocsConfig = {
  schemaVersion: 1,
  site: {
    title: "docsfn",
    description: "The documentation toolchain for superfunctions",
    basePath: "/docs",
    canonicalUrl: "https://docsfn.superfunctions.dev",
    showFooter: false,
    editLink: {
      pattern: "https://github.com/21nCo/super-functions/edit/dev/docsfn/docs/{path}",
    },
  },
  compat: { preset: "none" },
  content: {
    root: ".",
    docsDir: "content/docs",
    blogDir: "content/blog",
    apiDir: "content/api",
    pagesDir: "content/pages",
    assetsDir: "static",
    metaFileName: "meta.json",
  },
  navigation: {
    topNav: [
      { label: "Docs", href: "/docs" },
      { label: "API Reference", href: "/docs/api" },
      { label: "Blog", href: "/blog" },
      { label: "Changelog", href: "/changelog" },
      {
        label: "GitHub",
        href: "https://github.com/21nCo/super-functions/tree/dev/docsfn",
        external: true,
      },
    ],
    sidebars: {
      docs: { title: "Documentation", root: true, include: ["docs/**"] },
      api: { title: "API Reference", root: true, include: ["docs/api/**"] },
    },
  },
  collections: {
    changelog: {
      dir: "content/changelog",
      routeBase: "/changelog",
      feedPath: "/changelog/rss.xml",
      label: "Changelog",
      scope: "changelog",
    },
  },
  search: {
    enabled: true,
    scopes: ["docs", "api", "blog", "changelog"],
    bodyIndexing: "summary",
    routeScopeOverrides: [
      { pattern: "/docs/api", scope: "api" },
      { pattern: "/docs/api/**", scope: "api" },
    ],
  },
  auth: { enabled: false, mode: "public" },
  analytics: { enabled: false, provider: "watchfn", respectDnt: true },
};

export default config;
import { generateRSSFeed } from "@docsfn/core";
import { loadDocsSiteSource } from "$lib/server/docs-site-source";
import type { RequestHandler } from "./$types";

export const GET: RequestHandler = async ({ url }) => {
  const source = await loadDocsSiteSource();
  const collection = source.manifest.collections?.changelog;
  const origin = url.origin;
  const listRoute = collection?.listRoute ?? "/changelog";
  const feedPath = collection?.feedPath ?? `${listRoute}/rss.xml`;
  const changelogLink = `${origin}${listRoute}`;

  const xml = generateRSSFeed(source.manifest, {
    collectionId: "changelog",
    title: `${source.siteTitle} Changelog`,
    description: "Product updates and release notes.",
    link: changelogLink,
    feedHref: `${origin}${feedPath}`,
    itemHref: (post) => `${origin}${post.path}`,
  });

  return new Response(xml, {
    status: 200,
    headers: {
      "content-type": "application/rss+xml; charset=utf-8",
      "cache-control": "public, max-age=0, must-revalidate",
    },
  });
};
import { getCollectionPosts } from "@docsfn/sveltekit";
import { loadDocsSiteSource } from "$lib/server/docs-site-source";
import type { RequestHandler } from "./$types";

function redirectWithSearch(path: string, url: URL): Response {
  return new Response(null, {
    status: 302,
    headers: {
      location: `${path}${url.search}`,
      "cache-control": "public, max-age=0, must-revalidate",
    },
  });
}

export const GET: RequestHandler = async ({ url }) => {
  const source = await loadDocsSiteSource();
  const latest = getCollectionPosts("changelog", source.manifest)[0];

  if (!latest) {
    return new Response("No changelog entries found", {
      status: 404,
      headers: {
        "content-type": "text/plain; charset=utf-8",
        "cache-control": "public, max-age=0, must-revalidate",
      },
    });
  }

  return redirectWithSearch(latest.path, url);
};
