import { afterEach, describe, expect, it, vi } from "vitest";
import type {
  DocsSearchArtifact,
  DocsSearchDocument,
  DocsSearchField,
} from "./search";

const fields: DocsSearchField[] = [
  "title",
  "summary",
  "headings",
  "tags",
  "body",
];

function createDocument(
  id: string,
  scope: "docs" | "api",
  path: string,
  title: string,
): DocsSearchDocument {
  return {
    id,
    scope,
    kind: scope === "api" ? "api" : "page",
    path,
    title,
    summary: `${title} summary`,
    headings: [title],
    tags: ["adapter"],
    body: `${title} body`,
  };
}

function createArtifact(
  documents: DocsSearchDocument[],
  snapshot: DocsSearchArtifact["snapshot"],
): DocsSearchArtifact {
  return {
    schemaVersion: 1,
    engine: "searchfn",
    fields,
    scopes: ["api", "docs"],
    bodyIndexing: "summary",
    documents,
    snapshot,
    diagnostics: [],
    bytes: 0,
  };
}

afterEach(() => {
  vi.doUnmock("@searchfn/client");
  vi.resetModules();
});

describe("searchFnSearchAdapter", () => {
  it("builds, restores, maps, and filters a SearchFn snapshot directly", async () => {
    const { searchFnSearchAdapter } = await import("./searchfn-adapter");
    const documents = [
      createDocument("docs:adapter", "docs", "/docs/adapter", "Adapter guide"),
      createDocument("api:adapter", "api", "/api/adapter", "Adapter API"),
    ];
    const engine = await searchFnSearchAdapter.createIndexEngine({ fields });
    for (const document of documents) {
      engine.add({
        id: document.id,
        fields: {
          title: document.title,
          summary: document.summary,
          headings: document.headings.join(" "),
          tags: document.tags.join(" "),
          body: document.body,
        },
      });
    }
    const artifact = createArtifact(documents, engine.exportSnapshot());
    const runtime = await searchFnSearchAdapter.createRuntime({
      artifact,
      documents: new Map(documents.map((document) => [document.id, document])),
    });

    const results = await runtime.query({
      query: "adapter",
      scope: "api",
      limit: 10,
    });

    expect(searchFnSearchAdapter.name).toBe("searchfn");
    expect(results).toEqual([
      expect.objectContaining({
        id: "api:adapter",
        scope: "api",
        path: "/api/adapter",
        title: "Adapter API",
      }),
    ]);
  });

  it("translates missing client failures for build and runtime usage", async () => {
    vi.resetModules();
    vi.doMock("@searchfn/client", () => {
      throw new Error("searchfn client unavailable");
    });
    const { searchFnSearchAdapter } = await import("./searchfn-adapter");
    const emptyArtifact = createArtifact([], {
      postings: [],
      stats: [],
      documents: [],
      vocabulary: [],
    });

    await expect(
      searchFnSearchAdapter.createIndexEngine({ fields }),
    ).rejects.toMatchObject({
      code: "DOCS_SEARCH_BUILD_FAILED",
    });
    await expect(
      searchFnSearchAdapter.createRuntime({
        artifact: emptyArtifact,
        documents: new Map(),
      }),
    ).rejects.toMatchObject({
      code: "DOCS_ARTIFACT_INVALID",
    });
  });
});
import { describe, expect, it } from "vitest";
import {
  assertCompiledContentTrusted,
  assertDocsRouteAccess,
  assertSourceEntriesTrusted,
  redactSensitivePayload,
  resolveDocsAuthMode,
} from "./security";
import type { DocsSourceEntry } from "./provider";

function createEntry(overrides: Partial<DocsSourceEntry> = {}): DocsSourceEntry {
  return {
    id: "docs:index.mdx",
    collection: "docs",
    relativePath: "index.mdx",
    entryType: "content",
    frontmatter: {},
    body: "# Hello",
    ...overrides,
  };
}

describe("security", () => {
  it("blocks unsafe html in source entries by default (TV-SEC-001)", () => {
    expect(() =>
      assertSourceEntriesTrusted({
        entries: [
          createEntry({
            id: "docs:private.mdx",
            relativePath: "private.mdx",
            body: "# Unsafe\n\n<script>alert(1)</script>",
          }),
        ],
      })
    ).toThrowError(/DOCS_HTML_UNSAFE|unsafe HTML/);
  });

  it("allows explicit unsafe-html allowlist matches", () => {
    expect(() =>
      assertSourceEntriesTrusted({
        entries: [
          createEntry({
            id: "docs:legacy/unsafe.mdx",
            relativePath: "legacy/unsafe.mdx",
            body: "# Legacy\n\n<script>alert(1)</script>",
          }),
        ],
        policy: {
          allowUnsafeHtmlAllowlist: ["docs:legacy/unsafe.mdx"],
        },
      })
    ).not.toThrow();
  });

  it("blocks unsafe html in named dated collections", () => {
    expect(() =>
      assertSourceEntriesTrusted({
        entries: [
          createEntry({
            id: "collection:changelog:release.mdx",
            collection: "collection:changelog",
            relativePath: "release.mdx",
            body: "# Release\n\n<script>alert(1)</script>",
          }),
        ],
      })
    ).toThrowError(/DOCS_HTML_UNSAFE|unsafe HTML/);
  });

  it("ignores unsafe-looking html when it appears inside fenced code samples", () => {
    expect(() =>
      assertSourceEntriesTrusted({
        entries: [
          createEntry({
            id: "docs:guide/code-sample.mdx",
            relativePath: "guide/code-sample.mdx",
            body: [
              "# Guide",
              "",
              "```html",
              "<script>alert(1)</script>",
              "```",
              "",
              "Use `onClick=` only inside examples.",
            ].join("\n"),
          }),
        ],
      })
    ).not.toThrow();
  });

  it("applies the same trust model for compiled content artifacts", () => {
    expect(() =>
      assertCompiledContentTrusted({
        source: "# Unsafe\n\n<script>alert(1)</script>",
        sourcePath: "content/docs/unsafe.mdx",
      })
    ).toThrowError(/DOCS_HTML_UNSAFE|unsafe HTML/);
  });

  it("resolves canonical auth mode defaults", () => {
    expect(resolveDocsAuthMode({ auth: undefined })).toBe("public");
    expect(resolveDocsAuthMode({ auth: { enabled: true, mode: "private" } })).toBe(
      "private"
    );
    expect(resolveDocsAuthMode({ auth: { enabled: true, mode: "mixed" } })).toBe(
      "mixed"
    );
  });

  it("fails private routes with DOCS_AUTH_REQUIRED when no session is provided (TV-SEC-001)", async () => {
    await expect(
      assertDocsRouteAccess({
        config: {
          auth: {
            enabled: true,
            mode: "private",
          },
        },
        route: "/docs/private",
        session: null,
      })
    ).rejects.toThrowError(/DOCS_AUTH_REQUIRED|authentication is required/);
  });

  it("fails private routes with DOCS_AUTH_FORBIDDEN when authorization denies", async () => {
    await expect(
      assertDocsRouteAccess({
        config: {
          auth: {
          slug: "release",
          path: "/changelog/release",
          title: "Release",
          date: "2026-04-01",
          tags: ["release"],
          body: "Release details",
          frontmatter: {
            date: "2026-04-01",
            excerpt: "Release excerpt",
          },
        },
      ],
    });
    manifest.posts = {
      ...manifest.posts,
      ...Object.fromEntries(canonicalChangelog.posts.map((post) => [post.id, post])),
    };
    manifest.collections = {
      changelog: {
        id: canonicalChangelog.id,
        label: canonicalChangelog.label,
        scope: canonicalChangelog.scope,
        listRoute: canonicalChangelog.listRoute,
        feedPath: canonicalChangelog.feedPath,
        postOrder: canonicalChangelog.postOrder,
        tags: canonicalChangelog.tags,
        archives: canonicalChangelog.archives,
      },
    };

    const rss = generateRSSFeed(manifest, {
      collectionId: "ChangeLog",
      title: "Docs Changelog",
      description: "Product updates",
      link: "https://docs.example.com/changelog",
      feedHref: "https://docs.example.com/changelog/rss.xml",
      itemHref: (post) => `https://docs.example.com${post.path}`,
    });

    expect(rss).toContain("<title>Docs Changelog</title>");
    expect(rss).toContain("https://docs.example.com/changelog/release");
    expect(rss).not.toContain("/docs/blog/alpha");
    expect(rss).not.toContain("/docs/blog/beta");
  });

  it("does not fall back to blog posts for an unknown named collection", () => {
    const rss = generateRSSFeed(createManifest(), {
      collectionId: "missing",
      title: "Missing Collection",
      description: "No updates",
      link: "https://docs.example.com/missing",
    });

    expect(rss).not.toContain("/docs/blog/alpha");
    expect(rss).not.toContain("/docs/blog/beta");
    expect(rss).toContain(
      '<atom:link href="https://docs.example.com/missing/rss.xml"'
    );
  });
});

