+  let quoteDepth = 0;
+  let content = line;
+  while (true) {
+    const match = content.match(/^ {0,3}> ?/);
+    if (!match) {
+      break;
+    }
+    quoteDepth += 1;
+    content = content.slice(match[0].length);
+  }
