+
+export function isClosingFence(open: FenceState, candidate: FenceLineMatch): boolean {
+  return (
+    candidate.marker === open.marker &&
+    candidate.length >= open.length &&
+    candidate.quoteDepth === open.quoteDepth &&
+    /^[ \t]*$/.test(candidate.info)
