+  for (const line of lines) {
+    const { quoteDepth } = splitMarkdownContainerPrefix(line);
+    if (fence && quoteDepth < fence.quoteDepth) {
+      fence = null;
+    }
+    const fenceMatch = matchFenceLine(line, fence?.containerIndent ?? 0);
+    if (!fence && fenceMatch) {
