  resolveSession?: () => unknown | Promise<unknown>;
  isRoutePrivate?: (route: string) => boolean;
  authorize?: (input: { route: string; session: unknown }) => boolean | Promise<boolean>;
}

export interface DocsRouteAccessResult {
