+    visiting.add(node);
+    stack.push({
+      node,
+      children: Array.isArray(node) ? node : Object.values(node),
+      index: 0,
+    });
+  };
+
+  push(value);
+  while (stack.length > 0) {
+    const frame = stack[stack.length - 1];
+    if (frame.index >= frame.children.length) {
+      visiting.delete(frame.node);
+      visited.add(frame.node);
+      stack.pop();
