    const key = createCompiledCacheKey({
      kind: "post",
      id: post.id,
      framework,
      compatPreset: input.compatPreset,
    });
    postKeysById[post.id] = key;
    posts.set(
      key,
      resolveMarkdownRelativeLinks({
        compiled: compileSvelteContent({
          source: post.body,
          sourcePath: post.id,
          compatPreset: input.compatPreset,
        }),
        route: post.path,
        sourcePath: post.id,
      })
    );
  }

  return {
    framework,
    compatPreset: input.compatPreset,
    pages,
    posts,
    pageKeysById,
    postKeysById,
  };
