    path.resolve(normalizedCwd, "docsfn.config.mjs"),
    path.resolve(normalizedCwd, "docsfn.config.js"),
  ];
  if (input.configPath) {
    configFiles.push(path.resolve(normalizedCwd, input.configPath));
  }

  const invalidated = new Set<string>();
